window.COURSE = [{"id":1,"title":"Teen spirit","topic":"Teen life and the differences between generations","color":"#ff3d7f","vocab":[{"name":"Society","words":[["addicted to","adj phrase","unable to stop doing or using something","adicto/a a","Some people say teenagers are *addicted to* their phones."],["attitude","noun","the way you think and feel about something","actitud","My grandad has a very positive *attitude* to life."],["authority","noun","the power to give orders and make decisions","autoridad","Teachers have the *authority* to change the rules in class."],["dependent on","adj phrase","needing someone or something in order to exist or work","dependiente de","Adults are just as *dependent on* technology as teens."],["generation","noun","all the people born around the same time","generación","Each *generation* has its own music and fashion."],["judge","verb","to form an opinion about someone, often too quickly","juzgar","Don't *judge* people by the clothes they wear."],["represent","verb","to speak or act for a person or group","representar","Two students *represent* our class at school meetings."],["respect","noun / verb","a feeling that someone is important and deserves good treatment","respeto / respetar","We should show *respect* to older people."],["selfish","adj","thinking only about yourself and not about others","egoísta","It's *selfish* to eat all the pizza without sharing."],["spoiled","adj","used to getting everything you want","consentido/a, mimado/a","He's *spoiled* because his parents buy him everything."],["stand up for","phrasal verb","to defend a person or an idea","defender","She always *stands up for* her friends."],["values","noun (pl)","the principles and beliefs that are important to you","valores","My family has strong *values* about honesty."],["unfair","adj","not treating people equally or in the right way","injusto/a","It's *unfair* that the older students get more time."]]},{"name":"Phrasal verbs","words":[["ask somebody over","phrasal verb","to invite someone to your home","invitar a alguien a casa","I *asked* Leo *over* to watch the match."],["bring over","phrasal verb","to take something to someone's home","traer (a casa de alguien)","Can you *bring over* your speakers tonight?"],["come along","phrasal verb","to go somewhere with someone","venir, apuntarse","We're going to the park. Do you want to *come along*?"],["end up","phrasal verb","to be in a situation at the end, often without planning it","acabar (haciendo / en)","We got lost and *ended up* in a tiny village."],["get together","phrasal verb","to meet someone socially","reunirse, quedar","My cousins and I *get together* every summer."],["hang out","phrasal verb","to spend free time somewhere or with someone","pasar el rato","We usually *hang out* at the skate park."],["meet up with","phrasal verb","to meet someone by arrangement","quedar con","I'm *meeting up with* Sara after school."],["remind somebody of","phrasal verb","to make someone think of a person or thing","recordar a alguien a","This song *reminds* me *of* my first concert."],["show up","phrasal verb","to arrive, especially when people expect you","aparecer, presentarse","He *showed up* an hour late!"],["tell somebody off","phrasal verb","to speak angrily to someone because they did something wrong","regañar, reñir","The teacher *told* us *off* for talking."]]},{"name":"Extra: Relationships","extra":true,"words":[["advise","verb","to tell someone what you think they should do","aconsejar","My sister *advised* me to study more."],["appreciate","verb","to be grateful for something","agradecer, valorar","I really *appreciate* your help."],["assist","verb","to help someone","ayudar, asistir","Volunteers *assist* elderly people with shopping."],["commit (to)","verb","to promise to give your time or energy to something","comprometerse (a)","She *committed to* training three times a week."],["encourage","verb","to give someone confidence to do something","animar","My parents *encourage* me to follow my dreams."],["responsibility","noun","a duty to take care of something or someone","responsabilidad","Looking after a pet is a big *responsibility*."],["volunteer","verb / noun","to offer to do something without being paid","hacer voluntariado / voluntario","I *volunteer* at an animal shelter on Saturdays."]]}],"grammar":[{"id":"narrative","title":"Narrative tenses","short":"Past simple, past continuous and past perfect","slides":[{"k":"title","h":"Narrative tenses","sub":"Teen spirit: stories from different generations","hook":"Think of the first time you hung out with your friends without your parents. What happened? What was going on? What had you planned before?"},{"k":"table","h":"Three tenses, three jobs","cols":["Tense","Form","Use"],"rows":[["Past simple","verb + -ed / irregular (went, showed up)","Main events of the story, one after another"],["Past continuous","was / were + verb-ing","The background: what was happening"],["Past perfect","had + past participle","An action BEFORE another past action"]]},{"k":"text","h":"Past simple: the main events","p":["Use the past simple for the main actions of your story, in the order they happened."],"ex":["My friends **showed up** at eight, we **hung out** in the park and we **ended up** at Leo's house.","My grandad **stood up for** a classmate when the teacher was unfair.","Last Saturday I **asked** my cousins **over** to watch a film."]},{"k":"text","h":"Past continuous: the background","p":["Use the past continuous to set the scene, or for a longer action interrupted by a shorter one in the past simple.","We often use 'when' and 'while'."],"ex":["Everybody **was hanging out** in the square and music **was playing**.","We **were getting together** for a party when my dad **told** us **off** for the noise.","While my sister **was meeting up with** her friends, I **stayed** at home."]},{"k":"text","h":"Past perfect: one step further back","p":["Use the past perfect when you are already in the past and you want to go back to an earlier moment."],"ex":["When I arrived, my friends **had** already **brought over** the snacks.","Grandma was surprised because she **had never seen** a teenager so addicted to a phone.","I **'d asked** Sara over, but she didn't come along."]},{"k":"table","h":"Compare","cols":["Sentence","What happened first?"],"rows":[["When I got home, my parents told me off.","I got home → then they told me off"],["When I got home, my parents were telling my brother off.","They started before; it was in progress"],["When I got home, my parents had told my brother off.","It was finished before I arrived"]]},{"k":"context","h":"Grammar in context","kind":"Blog post · Teen life","title":"The party that went wrong","text":["Last summer I **asked** my friends **over** for a party. My parents **had gone** out for the evening, so we **had** the house to ourselves.","We **were dancing** and everyone **was singing** when the doorbell **rang**. It was my neighbour! She **told** us **off** because we **had woken up** her baby.","In the end, we **said** sorry and we **ended up** helping her with the shopping the next day. I think we showed some respect!"]},{"k":"mistakes","h":"Watch out!","items":[["When I showed up, the party already finished.","When I showed up, the party had already finished.","The party finished before you arrived."],["I was knowing it was unfair.","I knew it was unfair.","State verbs (know, like, want) don't use continuous forms."],["While we hung out at the park, it started to rain.","While we were hanging out at the park, it started to rain.","The longer background action needs the past continuous."]]},{"k":"check","q":"By the time we got to the concert, the band ___ on stage.","o":["showed up","was showing up","had shown up"],"a":2,"e":"The band appeared before we arrived → past perfect."},{"k":"check","q":"I ___ with my friends in town when my mum phoned me.","o":["was hanging out","had hung out","hang out"],"a":0,"e":"Hanging out is the background action interrupted by the phone call."},{"k":"sum","h":"Remember","p":["Past simple = what happened next.","Past continuous = what was happening (the scene).","Past perfect = what had happened before.","Key words: when, while, as, already, by the time, before, after."]}],"ex":{"basic":[{"q":"I ___ (meet) my best friend in primary school.","a":["met"]},{"q":"We ___ (watch) a film when the lights went out.","a":["were watching"]},{"q":"When I arrived, everyone ___ .","o":["had left","was leave","leaves"],"a":0},{"q":"She ___ the guitar when I came in.","o":["played","was playing","had play"],"a":1},{"q":"My dad ___ a mobile phone until he was 25.","o":["didn't have","wasn't having","hasn't had"],"a":0},{"q":"It ___ (rain) so we stayed at home.","a":["was raining","rained"]},{"r":"They were hanging out at the park when it started to rain."},{"q":"I was tired because I ___ (not / sleep) well.","a":["hadn't slept","had not slept"]}],"intermediate":[{"q":"By the time the teacher ___ , we had finished the test.","o":["came back","had come back","was coming back"],"a":0},{"q":"While my cousins ___ (play) video games, I was doing my homework.","a":["were playing"]},{"q":"I recognised the song because I ___ (hear) it before.","a":["had heard","'d heard"]},{"q":"When we got to the cinema, the film ___ (already / start).","a":["had already started","'d already started"]},{"q":"Mia ___ her phone, so she couldn't call us.","o":["had lost","was losing","loses"],"a":0},{"q":"As I ___ (walk) home, I saw an old friend.","a":["was walking"]},{"q":"They ___ (not / see) each other for years, so they talked all night.","a":["hadn't seen","had not seen"]},{"r":"She had never been to a concert before that night."}],"advanced":[{"q":"Hardly had I sat down when the phone ___ (ring).","a":["rang"]},{"q":"We ___ (drive) for hours when we realised we ___ (forget) the tickets.","a":["had been driving / had forgotten","were driving / had forgotten"],"h":"Write both verbs separated by /"},{"q":"Which sentence means the party was over before Tom arrived?","o":["When Tom arrived, everyone was leaving.","When Tom arrived, everyone had left.","When Tom arrived, everyone left."],"a":1},{"q":"My grandparents ___ (live) in the village for 40 years before they ___ (move) to the city.","a":["had lived / moved","had been living / moved"],"h":"Write both verbs separated by /"},{"q":"I ___ (not / realise) how late it was until my mum called.","a":["hadn't realised","didn't realise","had not realised","did not realise"]},{"q":"She told me off because I ___ (not / tidy) my room.","a":["hadn't tidied","had not tidied"]},{"q":"Choose the correct option: 'The crowd ___ when the band walked on stage.'","o":["was cheering","had cheered","cheering"],"a":0},{"r":"By the time we got there the shop had already closed."}]}},{"id":"usedto","title":"used to / would","short":"Past habits and past states","slides":[{"k":"title","h":"used to / would","sub":"Teen spirit: how life was different for other generations","hook":"What did your parents use to do at weekends when they were teenagers? Were they dependent on technology?"},{"k":"text","h":"used to + infinitive","p":["Use 'used to' for past habits and past states that are not true now."],"ex":["My parents' generation **used to** write letters to their friends.","Teenagers **didn't use to** be so dependent on technology.","**Did** your grandparents **use to** hang out in the town square?"]},{"k":"table","h":"Form of used to","cols":["","Form","Example"],"rows":[["+","subject + used to + verb","My mum used to have very strong values about manners."],["−","subject + didn't use to + verb","We didn't use to get together online."],["?","Did + subject + use to + verb?","Did young people use to respect authority more?"]],"note":"In negatives and questions it's 'use to' (no -d)."},{"k":"text","h":"would + infinitive","p":["Use 'would' for repeated actions (habits) in the past. It is common when people tell their memories.","Don't use 'would' for past states (be, have, live, like, know)."],"ex":["Every Saturday my grandad **would meet up with** his friends at the café.","My aunt **would** always **bring over** a cake when she visited us."]},{"k":"table","h":"used to or would?","cols":["Meaning","used to","would"],"rows":[["Past habit (repeated action)","✓ We used to hang out at the youth club.","✓ We would hang out at the youth club."],["Past state (be, have, live, like...)","✓ Teachers used to have more authority.","✗ Teachers would have more authority."],["One single action","✗","✗ → use the past simple"]]},{"k":"context","h":"Grammar in context","kind":"Interview · Generations","title":"Grandma remembers","text":["'When I was sixteen, we **didn't use to** have phones. If you wanted to see your friends, you **would** just go to the square and wait until they **showed up**.","My parents **used to** be very strict. They **would tell** me **off** if I came home late, but I think it was unfair!","We **used to** respect our teachers a lot. Today's generation is different, but I don't judge them. They have strong values too.'"]},{"k":"mistakes","h":"Watch out!","items":[["My grandparents didn't used to judge people.","My grandparents didn't use to judge people.","No -d after 'didn't'."],["Teachers would have more authority.","Teachers used to have more authority.","'have' is a state here, so 'would' is not possible."],["I'm used to hang out at the park as a child.","I used to hang out at the park as a child.","'be used to' means 'be accustomed to' – a different structure."]]},{"k":"check","q":"Teenagers in the 1960s ___ be less dependent on technology.","o":["would","used to","were used to"],"a":1,"e":"'be' is a state, so only 'used to' is correct."},{"k":"check","q":"___ your parents use to get told off at school?","o":["Did","Were","Would"],"a":0,"e":"Questions with used to: Did + subject + use to...?"},{"k":"sum","h":"Remember","p":["used to = past habits AND past states.","would = only past habits (repeated actions).","didn't use to / Did ... use to? (no -d).","For one action at one time, use the past simple."]}],"ex":{"basic":[{"q":"My mum ___ have a cassette player.","o":["used to","use to","would to"],"a":0},{"q":"We didn't ___ have the internet at home.","o":["used to","use to","would"],"a":1},{"q":"___ you use to play with dolls?","o":["Did","Do","Were"],"a":0},{"q":"When I was little, I ___ (use to / love) cartoons.","a":["used to love"]},{"q":"My grandad ___ (not / use to) watch TV.","a":["didn't use to","did not use to"]},{"q":"Every Sunday we ___ visit my aunt. (would)","a":["would"]},{"r":"People used to write letters to their friends."},{"q":"I ___ have short hair, but now it's long.","o":["used to","would","am used to"],"a":0}],"intermediate":[{"q":"Which is NOT correct? 'My dad ___ a skateboard.'","o":["used to have","would have","had"],"a":1},{"q":"Every night my grandma ___ (would / sing) to me.","a":["would sing"]},{"q":"___ your parents use to hang out in the town square?","a":["Did"]},{"q":"There ___ (use to / be) a cinema in our village.","a":["used to be"]},{"q":"Teenagers in the 80s ___ (not / use to) have mobile phones.","a":["didn't use to","did not use to"]},{"q":"On Saturdays, my mum and her friends ___ meet up at the café.","o":["would","were used to","use"],"a":0},{"q":"I ___ (not / like) vegetables, but now I love them. (use to)","a":["didn't use to like","did not use to like"]},{"r":"My brother would always show up late to dinner."}],"advanced":[{"q":"Correct the mistake: 'My grandparents would live in Galicia.'","a":["My grandparents used to live in Galicia.","My grandparents used to live in Galicia"]},{"q":"Which sentence is correct?","o":["Did you used to have a pet?","Did you use to have a pet?","Would you have a pet?"],"a":1},{"q":"When we were kids, we ___ (spend) hours outside. (use 'would')","a":["would spend"]},{"q":"I ___ (not / use to / be) so dependent on technology.","a":["didn't use to be","did not use to be"]},{"q":"Choose the best option: 'Last year I ___ to London once.'","o":["used to go","would go","went"],"a":2},{"q":"Rewrite with 'used to': 'In the past, my uncle smoked, but he doesn't now.' → My uncle ___ .","a":["used to smoke"]},{"q":"Rewrite with 'would': 'Every summer, we always went camping.' → Every summer, we ___ camping.","a":["would go"]},{"r":"Where did your parents use to go on holiday?"}]}}],"files":{"list":"downloads/unit1/vocabulary-list.pdf","vocab":{"basic":"downloads/unit1/vocabulary-basic.pdf","intermediate":"downloads/unit1/vocabulary-intermediate.pdf","advanced":"downloads/unit1/vocabulary-advanced.pdf"},"grammar":{"narrative":{"basic":"downloads/unit1/grammar-narrative-basic.pdf","intermediate":"downloads/unit1/grammar-narrative-intermediate.pdf","advanced":"downloads/unit1/grammar-narrative-advanced.pdf"},"usedto":{"basic":"downloads/unit1/grammar-usedto-basic.pdf","intermediate":"downloads/unit1/grammar-usedto-intermediate.pdf","advanced":"downloads/unit1/grammar-usedto-advanced.pdf"}}}},{"id":2,"title":"In business","topic":"Money, business and the skills you need to succeed","color":"#00a86b","vocab":[{"name":"Money and business","words":[["account","noun","an arrangement with a bank to keep your money there","cuenta (bancaria)","I opened a bank *account* when I turned sixteen."],["cash machine","noun","a machine in the street where you get money with a card","cajero automático","Is there a *cash machine* near here?"],["charge","verb","to ask someone to pay an amount of money","cobrar","The café *charges* two euros for a coffee."],["entrepreneur","noun","a person who starts their own business","emprendedor/a","She became an *entrepreneur* at the age of nineteen."],["expenses","noun (pl)","money that you spend to do something","gastos","Our *expenses* include rent and electricity."],["income","noun","money you receive, for example from work","ingresos","His *income* comes from selling T-shirts online."],["in exchange for","phrase","giving one thing and receiving another","a cambio de","I walk my neighbour's dog *in exchange for* some money."],["profit","noun","money you make after you pay all your costs","beneficio, ganancia","The school market made a *profit* of 300 euros."],["run","verb","to control or manage a business","dirigir, llevar (un negocio)","My aunt *runs* a small bakery."],["savings","noun (pl)","money that you keep and don't spend","ahorros","I bought my bike with my *savings*."],["set up","phrasal verb","to start a company or organization","montar, crear (una empresa)","They *set up* their business in a garage."],["wages","noun (pl)","money you get regularly for your work","salario, sueldo","The workers asked for higher *wages*."]]},{"name":"Personal skills","words":[["attention to detail","noun","the ability to notice small things carefully","atención al detalle","Designers need great *attention to detail*."],["communication skills","noun (pl)","the ability to express ideas clearly to others","habilidades comunicativas","Good *communication skills* help you work in a team."],["computer programming","noun","writing code to make computer software","programación informática","He learned *computer programming* online."],["creativity","noun","the ability to produce new and original ideas","creatividad","Her *creativity* makes her videos special."],["critical thinking","noun","analysing information carefully before you decide","pensamiento crítico","*Critical thinking* helps you spot fake news."],["design skills","noun (pl)","the ability to plan how something looks or works","habilidades de diseño","You need *design skills* to make a good logo."],["leadership skills","noun (pl)","the ability to guide and motivate a group","dotes de liderazgo","The captain has excellent *leadership skills*."],["negotiation skills","noun (pl)","the ability to discuss and reach an agreement","habilidades de negociación","Use your *negotiation skills* to get a better price."],["organizational skills","noun (pl)","the ability to plan and organize things well","capacidad organizativa","With good *organizational skills*, you never miss a deadline."],["time management","noun","using your time well to do all your tasks","gestión del tiempo","*Time management* is key during exam week."]]},{"name":"Extra: Personality adjectives","extra":true,"words":[["ambitious","adj","wanting very much to be successful","ambicioso/a","She's *ambitious* and wants her own company."],["calm","adj","relaxed and not worried","tranquilo/a","Stay *calm* during the interview."],["competitive","adj","wanting to win or be better than others","competitivo/a","My brother is very *competitive* at sports."],["curious","adj","wanting to learn or know about things","curioso/a","*Curious* people ask lots of questions."],["determined","adj","not letting anything stop you","decidido/a","He was *determined* to finish the marathon."],["generous","adj","happy to give money, time or help","generoso/a","It was *generous* of you to donate your savings."],["keen","adj","very interested or enthusiastic","entusiasta, con ganas","I'm *keen* to learn more about marketing."],["practical","adj","good at dealing with real problems","práctico/a","We need a *practical* solution."]]}],"grammar":[{"id":"presperf","title":"Present perfect simple and continuous","short":"Experiences, results and actions that continue","slides":[{"k":"title","h":"Present perfect simple & continuous","sub":"In business: young entrepreneurs","hook":"Have you ever earned your own money? How long have you been saving for something special?"},{"k":"table","h":"The two forms","cols":["","Simple","Continuous"],"rows":[["Form","have / has + past participle","have / has + been + verb-ing"],["+","She has set up a company.","She has been running it for a year."],["−","We haven't made a profit yet.","We haven't been charging enough."],["?","Have you opened a bank account?","How long have you been saving?"]]},{"k":"text","h":"Present perfect simple","p":["Use it for experiences (ever / never), results we can see now, and actions with 'already', 'just' and 'yet'.","It answers: How many? How much?"],"ex":["Have you **ever set up** a business?","Lola **has made** a profit of 200 euros this month.","I**'ve** just **opened** my first bank account."]},{"k":"text","h":"Present perfect continuous","p":["Use it for actions that started in the past and are still happening, or have just stopped and we can see the effects.","It answers: How long? It focuses on the activity."],"ex":["Marco **has been running** his online shop since 2023.","I'm exhausted because I**'ve been working** on my business plan.","How long **have** you **been saving** for a laptop?"]},{"k":"table","h":"for or since?","cols":["for + period of time","since + point in time"],"rows":[["I've had my bank account for two years.","I've had my bank account since 2024."],["She's been earning wages for six months.","She's been earning wages since June."],["They've been entrepreneurs for ages.","They've been entrepreneurs since they were fifteen."]]},{"k":"table","h":"Simple or continuous?","cols":["Simple (result / how many)","Continuous (activity / how long)"],"rows":[["I've counted my savings: 300 euros!","I've been saving since January."],["She has earned 500 euros in wages.","She has been working at the café all summer."],["They've set up the website.","They've been designing the logo."]],"note":"State verbs (know, like, have = own, believe) only use the simple: I've known my business partner for years."},{"k":"context","h":"Grammar in context","kind":"Magazine profile · Business","title":"Meet Ana, 16, entrepreneur","text":["Ana **has been making** jewellery since she was twelve. Two years ago she **set up** an online shop, and since then she **has sold** more than 1,000 bracelets.","'I**'ve been working** really hard,' she says. 'My expenses are low, so I**'ve made** a good profit. I**'ve** already **saved** enough for a new laptop!'","Her secret? Creativity, time management and great communication skills."]},{"k":"mistakes","h":"Watch out!","items":[["I've been knowing my business partner since 2020.","I've known my business partner since 2020.","'know' is a state verb."],["I run this shop for five years.","I've run / I've been running this shop for five years.","The situation continues up to now → present perfect."],["I've been selling 50 T-shirts this week.","I've sold 50 T-shirts this week.","A number of completed things → simple."]]},{"k":"check","q":"She ___ cupcakes since 9 a.m. for her new business – the kitchen smells amazing!","o":["has baked","has been baking","bakes"],"a":1,"e":"Focus on the activity and how long; we can see (and smell!) the effects."},{"k":"check","q":"Our company ___ a profit of 1,000 euros so far.","o":["has been making","has made","is making"],"a":1,"e":"'1,000 euros' is a result/number → simple."},{"k":"sum","h":"Remember","p":["Simple → result, experience, how many / how much.","Continuous → activity in progress, how long.","for + a period; since + a starting point.","No continuous with state verbs."]}],"ex":{"basic":[{"q":"I ___ (open) a bank account.","a":["have opened","'ve opened"]},{"q":"She ___ (work) here since June. (continuous)","a":["has been working","'s been working"]},{"q":"We have known each other ___ three years.","o":["for","since","ago"],"a":0},{"q":"He has been saving money ___ January.","o":["for","since","from"],"a":1},{"q":"___ you ever sold anything online?","o":["Have","Has","Did"],"a":0},{"q":"They ___ (not / make) a profit yet.","a":["haven't made","have not made"]},{"r":"How long have you been learning English?"},{"q":"My cousin ___ three companies!","o":["has set up","has been setting up","set up since"],"a":0}],"intermediate":[{"q":"I'm exhausted. I ___ (study) all afternoon.","a":["have been studying","'ve been studying"]},{"q":"Leo ___ (already / spend) all his wages.","a":["has already spent","'s already spent"]},{"q":"How many T-shirts ___ you ___ (sell) this week?","a":["have / sold"],"h":"Write both words separated by /"},{"q":"I ___ my best friend since primary school.","o":["have known","have been knowing","know"],"a":0},{"q":"Your hands are dirty! What ___ you ___ ?","o":["have / done","have / been doing","did / do"],"a":1},{"q":"We ___ (not / hear) from the bank yet.","a":["haven't heard","have not heard"]},{"q":"Sara ___ (run) her online shop for two years.","a":["has been running","has run","'s been running","'s run"]},{"r":"She has just set up her own business."}],"advanced":[{"q":"Rewrite: 'I started working here in 2022.' → I ___ here since 2022.","a":["have been working","have worked","'ve been working","'ve worked"]},{"q":"Rewrite: 'This is my first time in a job interview.' → I ___ in a job interview before.","a":["have never been","'ve never been"]},{"q":"Which sentence is correct?","o":["I've been owning this phone for a year.","I've owned this phone for a year.","I own this phone since a year."],"a":1},{"q":"It's the third time he ___ (lose) his card this month.","a":["has lost","'s lost"]},{"q":"We ___ (try) to contact the bank all morning, but nobody ___ (answer).","a":["have been trying / has answered","'ve been trying / has answered"],"h":"Write both verbs separated by /"},{"q":"Rewrite: 'When did you start saving?' → How long ___ ?","a":["have you been saving"]},{"q":"Choose the best option: 'Prices ___ steadily over the last year.'","o":["have been rising","have risen three","rose since"],"a":0},{"r":"How much money have you saved so far?"}]}},{"id":"questions","title":"Question forms","short":"Subject and object questions, indirect questions","slides":[{"k":"title","h":"Question forms","sub":"In business: the job interview","hook":"What questions do people ask in a job interview? Which personal skills would you talk about?"},{"k":"table","h":"Object questions","cols":["Question word","Auxiliary","Subject","Verb..."],"rows":[["What skills","do","you","have?"],["Where","did","she","set up her business?"],["How much","does","the bank","charge?"]],"note":"Remember QUASI: Question word – Auxiliary – Subject – Infinitive."},{"k":"text","h":"Subject questions","p":["When the question word (who, what, which) is the SUBJECT, we don't use do / does / did. The word order is the same as a statement."],"ex":["**Who runs** the company? (Somebody runs the company.)","**What happened** to your savings?","**Which bank charges** the lowest fees?"]},{"k":"table","h":"Subject or object?","cols":["Subject question","Object question"],"rows":[["Who paid the entrepreneur?  (The bank paid her.)","Who did the entrepreneur pay?  (She paid her workers.)"],["What made a profit?  (The café made a profit.)","What did you buy with your wages?"]]},{"k":"text","h":"Indirect questions","p":["Indirect questions are more polite – perfect for interviews! Start with 'Could you tell me...', 'Do you know...', 'I'd like to know...'. Then use statement word order (no do/does/did).","For yes/no questions, use 'if' or 'whether'."],"ex":["Could you tell me **where the nearest cash machine is**?","Do you know **how much the bank charges**?","I'd like to know **if you have leadership skills**."]},{"k":"context","h":"Grammar in context","kind":"Dialogue · Job interview","title":"A summer job at the café","text":["Manager: So, **what do you do** in your free time?","Leo: I design websites. I'm good at computer programming and I have good organizational skills.","Manager: Great. **Have you ever worked** with money?","Leo: Yes, I help at my aunt's shop. Could you tell me **what the wages are**? And I'd like to know **whether I can work** at weekends.","Manager: Of course. **Who told** you about this job?"]},{"k":"mistakes","h":"Watch out!","items":[["Who did set up Apple?","Who set up Apple?","Subject question: no 'did'."],["Could you tell me where is the cash machine?","Could you tell me where the cash machine is?","Indirect question: statement order."],["How much you earn?","How much do you earn?","Object questions need an auxiliary."]]},{"k":"check","q":"Who ___ the business with you?","o":["did set up","set up","did sets up"],"a":1,"e":"'Who' is the subject, so no auxiliary."},{"k":"check","q":"Do you know what time ___ ?","o":["does the bank open","the bank opens","opens the bank"],"a":1,"e":"Indirect question → statement word order."},{"k":"sum","h":"Remember","p":["Object questions: QW + auxiliary + subject + verb.","Subject questions: who / what + verb (no do / did).","Indirect questions: polite phrase + statement order.","Yes/no indirect questions use if / whether."]}],"ex":{"basic":[{"q":"___ do you live?","o":["Where","Who","Which"],"a":0},{"q":"What ___ you do yesterday?","o":["did","do","were"],"a":0},{"q":"Who ___ (open) the window?","a":["opened"]},{"q":"How old ___ your sister?","o":["is","does","has"],"a":0},{"q":"___ you got any work experience?","o":["Have","Do","Are"],"a":0},{"r":"What time does the shop open?"},{"q":"How much ___ this cost?","o":["does","do","is"],"a":0},{"q":"Where ___ you go on holiday last summer?","a":["did"]}],"intermediate":[{"q":"Who ___ you this job? (offer – past)","a":["offered"]},{"q":"Who ___ you ___ to at the meeting? (talk – past)","a":["did / talk"],"h":"Write both words separated by /"},{"q":"Could you tell me where ___ ?","o":["the bank is","is the bank","does the bank"],"a":0},{"q":"What ___ to your phone?","o":["did happen","happened","was happen"],"a":1},{"q":"Do you know ___ the manager is here?","o":["if","that","what"],"a":0},{"q":"How long ___ you been running your business?","a":["have"]},{"q":"Which company ___ (pay) the best wages?","a":["pays","paid"]},{"r":"Could you tell me how much the course costs?"}],"advanced":[{"q":"Make an indirect question: 'When does the interview start?' → Do you know ___ ?","a":["when the interview starts"]},{"q":"Make an indirect question: 'Have you got a CV?' → I'd like to know ___ .","a":["if you have got a CV","whether you have got a CV","if you've got a CV","whether you've got a CV","if you have a CV","whether you have a CV"]},{"q":"Write the question for the underlined part: 'Sofía set up the company.' (ask about Sofía)","a":["Who set up the company?","Who set up the company"]},{"q":"Write the question: 'She called the bank.' (ask about the bank)","a":["Who did she call?","Who did she call","What did she call?"]},{"q":"Which question is correct?","o":["What did make you choose this job?","What made you choose this job?","What you made choose this job?"],"a":1},{"q":"Make an indirect question: 'Why did you leave your last job?' → Can you explain ___ ?","a":["why you left your last job"]},{"q":"Correct the mistake: 'Can you tell me what time is it?'","a":["Can you tell me what time it is?","Can you tell me what time it is"]},{"r":"I wonder whether they will offer me the job."}]}}],"files":{"list":"downloads/unit2/vocabulary-list.pdf","vocab":{"basic":"downloads/unit2/vocabulary-basic.pdf","intermediate":"downloads/unit2/vocabulary-intermediate.pdf","advanced":"downloads/unit2/vocabulary-advanced.pdf"},"grammar":{"presperf":{"basic":"downloads/unit2/grammar-presperf-basic.pdf","intermediate":"downloads/unit2/grammar-presperf-intermediate.pdf","advanced":"downloads/unit2/grammar-presperf-advanced.pdf"},"questions":{"basic":"downloads/unit2/grammar-questions-basic.pdf","intermediate":"downloads/unit2/grammar-questions-intermediate.pdf","advanced":"downloads/unit2/grammar-questions-advanced.pdf"}}}},{"id":3,"title":"Planet Earth","topic":"The environment, activism and making a difference","color":"#0a84ff","vocab":[{"name":"Fundraising collocations","words":[["achieve a goal","collocation","to succeed in doing what you planned","alcanzar un objetivo","We *achieved our goal* of planting 100 trees."],["donate money","collocation","to give money to help a cause","donar dinero","Thousands of people *donated money* to the charity."],["find sponsors","collocation","to get people or companies to support you with money","encontrar patrocinadores","We need to *find sponsors* for the charity run."],["give your time","collocation","to help without being paid","dedicar tu tiempo","Volunteers *give their time* to clean the beach."],["hold an event","collocation","to organize a public activity","celebrar un evento","Our school will *hold an event* on Earth Day."],["launch a campaign","collocation","to start a planned set of actions for a cause","lanzar una campaña","They *launched a campaign* against plastic bags."],["make a difference","collocation","to have a positive effect","marcar la diferencia","Small actions can *make a difference*."],["promote a cause","collocation","to help people know about and support an idea","promover una causa","Influencers can *promote a cause* to millions."],["raise funds","collocation","to collect money for a purpose","recaudar fondos","We sold cakes to *raise funds* for the shelter."],["reach a target","collocation","to get to the number or amount you wanted","alcanzar una meta","We *reached our target* of 500 euros!"],["save the planet","collocation","to protect the Earth from damage","salvar el planeta","Everyone can help to *save the planet*."],["sign a petition","collocation","to write your name on a document asking for change","firmar una petición","Over 2,000 students *signed the petition*."]]},{"name":"Nature and the environment","words":[["absorb","verb","to take in a liquid, gas or energy","absorber","Trees *absorb* carbon dioxide."],["carbon footprint","noun","the amount of CO2 your activities produce","huella de carbono","Cycling reduces your *carbon footprint*."],["climate change","noun","long-term changes in the Earth's weather and temperature","cambio climático","*Climate change* is melting the ice at the poles."],["damage","noun / verb","harm that makes something worse","daño / dañar","Oil spills *damage* the ocean."],["green","adj","good for the environment","ecológico/a, verde","Our school is becoming more *green*."],["greenhouse gas","noun","a gas that traps heat in the atmosphere","gas de efecto invernadero","Methane is a powerful *greenhouse gas*."],["habitat","noun","the natural home of an animal or plant","hábitat","The lynx is losing its *habitat*."],["loss","noun","when you no longer have something","pérdida","The *loss* of forests is a serious problem."],["reduce","verb","to make something smaller or less","reducir","We must *reduce* the amount of plastic we use."],["species","noun","a group of animals or plants of the same type","especie","Many *species* are in danger of extinction."],["suffer","verb","to experience pain or problems","sufrir","Coral reefs *suffer* when the sea gets warmer."],["support","verb","to help or agree with someone or something","apoyar","I *support* the campaign to protect the river."],["sustainable","adj","able to continue without harming the environment","sostenible","Bamboo is a *sustainable* material."],["threaten","verb","to put something in danger","amenazar","Pollution *threatens* marine life."]]},{"name":"Extra: Verbs related to change","extra":true,"words":[["ensure","verb","to make certain that something happens","asegurar, garantizar","Recycling bins *ensure* that less waste goes to landfill."],["establish","verb","to start something that will last","establecer, fundar","She *established* a youth climate group."],["inspire","verb","to give someone the wish to do something","inspirar","Greta Thunberg *inspired* millions of teens."],["recreate","verb","to make something exist again","recrear","The project *recreated* a natural wetland."],["transform","verb","to change something completely","transformar","They *transformed* the car park into a garden."]]}],"grammar":[{"id":"future","title":"Future tenses","short":"will, be going to, present simple and present continuous for the future","slides":[{"k":"title","h":"Talking about the future","sub":"Planet Earth: plans to make a difference","hook":"What is your school going to do for the environment this year? What do you think the planet will be like in 2050?"},{"k":"table","h":"Four ways to talk about the future","cols":["Form","Use","Example"],"rows":[["will + verb","Predictions (opinion), instant decisions, promises, offers","I think climate change will threaten more species. / I'll sign the petition!"],["be going to + verb","Plans and intentions; predictions with evidence","We're going to launch a campaign. / Look at the smoke! The forest is going to burn."],["Present continuous","Fixed arrangements (time, place, people)","We're meeting our sponsors on Friday."],["Present simple","Timetables and schedules","The climate march starts at 10 a.m."]]},{"k":"text","h":"will","p":["Use 'will' when you decide something at the moment of speaking, for promises and offers, and for predictions based on opinion (I think, probably, I'm sure)."],"ex":["You need volunteers? I**'ll give** my time on Saturday!","I promise I **won't use** plastic bags any more.","I think green energy **will be** cheaper in the future."]},{"k":"text","h":"be going to","p":["Use 'be going to' for plans you've already decided, and for predictions based on what you can see now."],"ex":["Our eco club **is going to raise** funds for the animal shelter.","We**'re going to reduce** our carbon footprint: no more car to school!","Look at the river! The factory **is going to damage** the habitat."]},{"k":"text","h":"Present tenses for the future","p":["Present continuous: arrangements already organized (in your diary).","Present simple: timetables, programmes, schedules."],"ex":["We**'re holding** a fundraising event on Saturday.","The bus to the nature reserve **leaves** at 8:15 tomorrow."]},{"k":"context","h":"Grammar in context","kind":"Group chat · Eco club","title":"Save the river!","text":["Marta: Big news! We**'re meeting** the mayor on Monday at 5. 🙌","Dani: Amazing. What **are** we **going to ask** for?","Marta: We**'re going to launch** a campaign to protect the river habitat. Many species are suffering.","Dani: I**'ll make** the posters! I think lots of people **will sign** the petition.","Marta: Perfect. The meeting **finishes** at 6, so we can hold an event after."]},{"k":"mistakes","h":"Watch out!","items":[["You need help? OK, I'm going to help you!","You need help? OK, I'll help you!","Decision at the moment of speaking → will."],["I will meet the sponsors at 6. It's in my diary.","I'm meeting the sponsors at 6.","Fixed arrangement → present continuous."],["When we will reach our target, we'll celebrate.","When we reach our target, we'll celebrate.","After when / as soon as / before, use the present simple."]]},{"k":"check","q":"Look at those dark clouds over the forest! It ___ .","o":["will rain","is going to rain","rains"],"a":1,"e":"Prediction with evidence → be going to."},{"k":"check","q":"The bus to the climate march ___ at 8:30.","o":["leaves","is going to leave","will leaving"],"a":0,"e":"Timetable → present simple."},{"k":"sum","h":"Remember","p":["will → decisions now, promises, opinions about the future.","going to → plans and evidence.","present continuous → arrangements.","present simple → timetables."]}],"ex":{"basic":[{"q":"I'm thirsty. – I ___ get you some water.","o":["will","am going to","am"],"a":0},{"q":"We ___ (going to / plant) trees next weekend.","a":["are going to plant","'re going to plant"]},{"q":"The film ___ at 9 p.m.","o":["starts","will starting","is start"],"a":0},{"q":"I ___ (meet) my friends tonight. We've already decided where.","a":["am meeting","'m meeting"]},{"q":"I think it ___ (be) sunny tomorrow.","a":["will be","'ll be"]},{"q":"Careful! You ___ fall!","o":["are going to","will to","fall"],"a":0},{"r":"We are going to sign the petition."},{"q":"I promise I ___ (not / forget) to recycle.","a":["won't forget","will not forget"]}],"intermediate":[{"q":"She ___ (fly) to Brussels on Monday – she has her ticket.","a":["is flying","'s flying"]},{"q":"Scientists think temperatures ___ (rise) by 2°C.","a":["will rise"]},{"q":"The bag is heavy. – Don't worry, I ___ carry it.","o":["'ll","'m going to","carry"],"a":0},{"q":"What ___ you ___ (do) after school today? (plan)","a":["are / going to do"],"h":"Write both parts separated by /"},{"q":"The eco-fair ___ (open) at 10 and closes at 6.","a":["opens"]},{"q":"When I ___ (finish) school, I'll study environmental science.","a":["finish"]},{"q":"Look at those dark clouds. There ___ a storm.","o":["is going to be","will being","is being"],"a":0},{"r":"We are holding a fundraising event on Saturday."}],"advanced":[{"q":"Choose the most natural option: 'We've booked the hall. We ___ the event on 5 June.'","o":["will hold","are holding","hold"],"a":1},{"q":"I ___ (call) you as soon as I ___ (get) the results.","a":["will call / get","'ll call / get"],"h":"Write both verbs separated by /"},{"q":"Correct the mistake: 'If it will rain, we'll cancel the march.'","a":["If it rains, we'll cancel the march.","If it rains, we will cancel the march."]},{"q":"Which sentence shows a prediction based on evidence?","o":["I think more people will cycle.","The river is rising fast. It's going to flood.","We're flooding on Sunday."],"a":1},{"q":"The train ___ (arrive) at 11:40, so we ___ (meet) you at the station at 12. (timetable / arrangement)","a":["arrives / are meeting","arrives / 're meeting"],"h":"Write both verbs separated by /"},{"q":"A: I've forgotten my reusable bag. B: No problem. I ___ (lend) you mine.","a":["'ll lend","will lend"]},{"q":"Probably most cars ___ (be) electric by 2040.","a":["will be"]},{"r":"I don't think we will reach our target this year."}]}},{"id":"futcont","title":"Future continuous","short":"Actions in progress at a time in the future","slides":[{"k":"title","h":"Future continuous","sub":"Planet Earth: where will you be in 2050?","hook":"What will you be doing this time next year? Will people be living in sustainable cities in 2050?"},{"k":"table","h":"Form","cols":["","Form","Example"],"rows":[["+","will be + verb-ing","We will be using only green energy."],["−","won't be + verb-ing","We won't be driving petrol cars."],["?","Will + subject + be + verb-ing?","Will you be volunteering at the beach clean-up?"]]},{"k":"text","h":"Use 1: in progress at a future time","p":["We use the future continuous for an action that will be happening at a particular moment in the future."],"ex":["At 10 a.m. tomorrow, we**'ll be marching** to save the planet.","This time next week I**'ll be planting** trees with the eco club.","In 2050, people **will be living** in green, sustainable cities."]},{"k":"text","h":"Use 2: polite questions about plans","p":["It's a polite way to ask about someone's plans, especially before asking for a favour."],"ex":["**Will** you **be using** your bike tomorrow? I want to reduce my carbon footprint!","**Will** you **be coming** to the fundraising event?"]},{"k":"table","h":"Future simple vs future continuous","cols":["will + verb","will be + verb-ing"],"rows":[["The event will start at 5. (a moment)","At 5:30 we'll be raising funds. (in progress)"],["I'll donate money tonight.","Don't call at 8 – I'll be signing petitions online."]]},{"k":"context","h":"Grammar in context","kind":"Letter to the future","title":"Dear me in 2050","text":["Dear future me, I hope you **will be living** in a city with clean air. I imagine that most people **will be cycling** to work and that factories **won't be producing** so much greenhouse gas.","Maybe you **will be working** as a scientist, helping endangered species to survive. Maybe you **will be teaching** children how to protect their habitat.","Whatever you **are doing**, I hope you are still making a difference!"]},{"k":"mistakes","h":"Watch out!","items":[["This time tomorrow I will signing petitions.","This time tomorrow I will be signing petitions.","Don't forget 'be'."],["At 9 p.m. I'll be knowing if we reached our target.","At 9 p.m. I'll know if we reached our target.","State verbs don't usually use continuous forms."]]},{"k":"check","q":"Don't phone me at 7. I ___ trees with the eco club.","o":["'ll plant","'ll be planting","plant"],"a":1,"e":"In progress at that time → future continuous."},{"k":"check","q":"___ you be using the car later? We need to take the donations to the shelter.","o":["Will","Are","Do"],"a":0,"e":"Polite question about plans: Will you be + -ing?"},{"k":"sum","h":"Remember","p":["will be + -ing = in progress at a future moment.","Time expressions: this time next week, at 8 tomorrow, in 2050, in ten years' time.","Will you be + -ing? = a polite question about plans."]}],"ex":{"basic":[{"q":"This time tomorrow I ___ (fly) to London.","a":["will be flying","'ll be flying"]},{"q":"At 8 p.m. we ___ dinner.","o":["will be having","will having","are have"],"a":0},{"q":"In 2040, people ___ (not / drive) petrol cars.","a":["won't be driving","will not be driving"]},{"q":"___ you be studying tonight?","o":["Will","Are","Do"],"a":0},{"q":"Next summer I'll ___ working at a campsite.","o":["be","being","to be"],"a":0},{"r":"This time next week we will be camping."},{"q":"At midnight they ___ (sleep).","a":["will be sleeping","'ll be sleeping"]},{"q":"Will she be ___ to the meeting?","o":["coming","come","comes"],"a":0}],"intermediate":[{"q":"In ten years' time, I ___ (live) in another country.","a":["will be living","'ll be living"]},{"q":"Don't call at 6. We ___ (watch) the documentary.","a":["will be watching","'ll be watching"]},{"q":"Choose: 'The clean-up ___ at 9.' (a moment)","o":["will start","will be starting at","is be starting"],"a":0},{"q":"___ (you / use) your tablet this afternoon? Can I borrow it?","a":["Will you be using"]},{"q":"By 2050 many species ___ (struggle) to survive.","a":["will be struggling"]},{"q":"At 11 o'clock tomorrow, the students ___ an exam.","o":["will be doing","will be do","do"],"a":0},{"q":"I ___ (not / work) this weekend, so I can help.","a":["won't be working","will not be working"]},{"r":"What will you be doing at this time tomorrow?"}],"advanced":[{"q":"Correct the mistake: 'This time next year I will be knowing my exam results.'","a":["This time next year I will know my exam results.","This time next year I'll know my exam results."]},{"q":"Which sentence is more polite?","o":["Will you come to my party?","Will you be coming to my party?","Do you come to my party?"],"a":1},{"q":"Complete with the right form: 'When you arrive, I ___ (wait) for you at the entrance.'","a":["will be waiting","'ll be waiting"]},{"q":"Future simple or continuous? 'I promise I ___ (recycle) more.'","a":["will recycle","'ll recycle"]},{"q":"Rewrite: 'I'm going to start my shift at 2 and finish at 10.' → At 6, I ___ .","a":["will be working","'ll be working"]},{"q":"In the future, robots ___ (do) most of the dangerous jobs.","a":["will be doing","will do"]},{"q":"Choose: 'Hurry up! The march ___ in five minutes.'","o":["will be starting","will be start","starting"],"a":0},{"r":"Will you be going past the supermarket on your way home?"}]}}],"files":{"list":"downloads/unit3/vocabulary-list.pdf","vocab":{"basic":"downloads/unit3/vocabulary-basic.pdf","intermediate":"downloads/unit3/vocabulary-intermediate.pdf","advanced":"downloads/unit3/vocabulary-advanced.pdf"},"grammar":{"future":{"basic":"downloads/unit3/grammar-future-basic.pdf","intermediate":"downloads/unit3/grammar-future-intermediate.pdf","advanced":"downloads/unit3/grammar-future-advanced.pdf"},"futcont":{"basic":"downloads/unit3/grammar-futcont-basic.pdf","intermediate":"downloads/unit3/grammar-futcont-intermediate.pdf","advanced":"downloads/unit3/grammar-futcont-advanced.pdf"}}}},{"id":4,"title":"Picture this","topic":"Photography and the stories behind images","color":"#8b3dff","vocab":[{"name":"Photography","words":[["angle","noun","the position from which you look at or photograph something","ángulo","Try taking the photo from a low *angle*."],["close-up","noun","a photo taken very near the subject","primer plano","This *close-up* shows the details of the flower."],["contrast","noun","a clear difference between light and dark or colours","contraste","Black and white photos often have strong *contrast*."],["depth","noun","the feeling of distance in a picture","profundidad","The trees in front give the photo more *depth*."],["effective","adj","producing the result you want","eficaz, efectivo/a","Simple images are often the most *effective*."],["flash","noun","a bright light on a camera used in the dark","flash","Turn off the *flash* in the museum."],["frame","noun / verb","the edges of a picture; to arrange the edges","encuadre / encuadrar","*Frame* your subject in the centre of the picture."],["highlight","verb","to make something easy to notice","resaltar, destacar","The sunlight *highlights* her face."],["impact","noun","a strong effect on people","impacto","That photo had a huge *impact* on the public."],["point at","phrasal verb","to aim something towards a person or thing","apuntar a, señalar","*Point* the camera *at* the bird and wait."],["set up","phrasal verb","to prepare equipment so it's ready to use","montar, preparar","It took ten minutes to *set up* the tripod."],["shoot","verb","to take photos or film","fotografiar, rodar","They *shot* the video on the beach."],["shot","noun","a photo, or a part of a film","toma, foto","That's the best *shot* of the whole trip."],["subject","noun","the person or thing in a photo","sujeto, motivo","The *subject* of the portrait is her grandmother."],["viewer","noun","a person who looks at an image or watches something","espectador/a","The photo makes the *viewer* feel sad."]]},{"name":"Prepositional phrases","words":[["at first","phrase","at the beginning","al principio","*At first* I didn't like the photo, but now I love it."],["by chance","phrase","without planning it","por casualidad","He took the famous picture *by chance*."],["by far","phrase","by a big amount (with superlatives)","con diferencia","This is *by far* the best photo in the exhibition."],["in a hurry","phrase","doing something quickly because you have little time","con prisa","I took the shot *in a hurry* and it was blurry."],["in contrast","phrase","used to show a difference","en cambio, por el contrario","The city is noisy. *In contrast*, the village is peaceful."],["in fact","phrase","used to give more true information","de hecho","It looks real. *In fact*, it's a painting."],["in focus / out of focus","phrase","clear / not clear in a photo","enfocado / desenfocado","The background is *out of focus*."],["in general","phrase","usually, in most situations","en general","*In general*, natural light is better."],["out of the ordinary","phrase","unusual, different","fuera de lo común","Look for subjects that are *out of the ordinary*."]]},{"name":"Extra: Adjective suffixes","extra":true,"words":[["cheerful","adj","happy and positive","alegre","It's a bright, *cheerful* picture."],["cultural","adj","related to art, music, traditions","cultural","The city has a rich *cultural* life."],["enjoyable","adj","that you enjoy","agradable, divertido/a","The workshop was really *enjoyable*."],["hopeless","adj","very bad at something; without hope","inútil, desesperado/a","I'm *hopeless* at taking selfies."],["impressive","adj","that makes you admire it","impresionante","The exhibition was *impressive*."],["natural","adj","not made by people; normal","natural","I prefer *natural* light."],["pleasant","adj","nice, enjoyable","agradable","We had a *pleasant* walk."],["political","adj","related to government and power","político/a","Some photos carry a *political* message."],["powerful","adj","having a strong effect","potente, poderoso/a","It's a very *powerful* image."],["useless","adj","not useful at all","inútil","This old camera is *useless*."],["valuable","adj","worth a lot of money or very useful","valioso/a","The original print is very *valuable*."]]}],"grammar":[{"id":"deduction","title":"Modals of deduction","short":"must, might, could, can't – present and past","slides":[{"k":"title","h":"Modals of deduction","sub":"Picture this: the story behind the photo","hook":"Look at a famous photo. Where might it have been taken? How must the subject have felt?"},{"k":"table","h":"How sure are you?","cols":["Certainty","Present","Past"],"rows":[["~100% yes","must + verb","must have + past participle"],["Maybe (50%)","might / may / could + verb","might / may / could have + past participle"],["~100% no","can't / couldn't + verb","can't / couldn't have + past participle"]]},{"k":"text","h":"Present deduction","p":["We use these modals to guess about a photo or a situation now, based on the evidence we can see."],"ex":["She's carrying a tripod. She **must be** a photographer.","The subject is smiling. He **might be** looking at his family.","That **can't be** a real photo – the contrast is impossible!"]},{"k":"text","h":"Continuous form","p":["For actions in progress now: modal + be + verb-ing."],"ex":["They **must be shooting** a close-up – look at the camera angle.","The photographer **could be pointing** the camera at the bird."]},{"k":"text","h":"Past deduction","p":["To guess about the past: modal + have + past participle."],"ex":["The photographer **must have waited** hours for that shot.","This picture **might have been** taken by chance.","He **can't have used** a flash – the photo is so dark."]},{"k":"context","h":"Grammar in context","kind":"Article · Famous photos","title":"What happened before the shot?","text":["In this black-and-white photo, eleven workers are eating lunch on a steel beam high above New York. They **must have been** very brave – or very used to heights!","Some experts think the shot **might have been** planned by the photographer to promote the new skyscraper. The men **can't have been** completely relaxed, but they look calm.","The viewer **must feel** the impact of the empty space below them. In fact, that is why the photo is so powerful."]},{"k":"mistakes","h":"Watch out!","items":[["He mustn't be the photographer – he hasn't got a camera.","He can't be the photographer – he hasn't got a camera.","For negative deduction, use can't, not mustn't."],["She must took the shot from a helicopter.","She must have taken the shot from a helicopter.","Past deduction: modal + have + past participle."],["The photo could have be edited.","The photo could have been edited.","Use the past participle 'been'."]]},{"k":"check","q":"The whole photo is out of focus. The photographer ___ moved the camera.","o":["must have","can't have","must"],"a":0,"e":"Strong evidence about the past → must have + participle."},{"k":"check","q":"That ___ the original photo. The original is in a museum in Paris!","o":["must be","might be","can't be"],"a":2,"e":"It's impossible → can't be."},{"k":"sum","h":"Remember","p":["must = I'm sure it's true.","might / may / could = it's possible.","can't / couldn't = I'm sure it's not true.","Past: modal + have + past participle."]}],"ex":{"basic":[{"q":"He has a lot of cameras. He ___ love photography.","o":["must","can't","mustn't"],"a":0},{"q":"She isn't answering. She ___ be busy.","o":["might","can't","has"],"a":0},{"q":"That ___ be Tom. He's on holiday in Peru.","o":["can't","must","might"],"a":0},{"q":"Look at the snow. It ___ be very cold there.","a":["must"]},{"q":"I'm not sure where she is. She ___ be in the darkroom.","o":["could","must","can't"],"a":0},{"q":"This photo ___ be very old – it's in black and white.","o":["might","can't","mustn't"],"a":0},{"r":"They must be on holiday in that photo."},{"q":"He looks very happy. He ___ have won the prize.","o":["must","can't","mustn't"],"a":0}],"intermediate":[{"q":"The ground is wet. It ___ (rain) last night.","a":["must have rained"]},{"q":"She ___ (not / take) this photo. She doesn't have a camera.","a":["can't have taken","couldn't have taken"]},{"q":"I can't find my phone. I ___ (leave) it at school. (possibility)","a":["might have left","may have left","could have left"]},{"q":"They're laughing a lot. They ___ (have) a great time. (present continuous)","a":["must be having"]},{"q":"The photo is blurry. He ___ moved the camera.","o":["must have","can't have","must"],"a":0},{"q":"That ___ been easy to photograph – the lion was running!","o":["can't have","must have","might"],"a":0},{"q":"Where's Laura? – I'm not sure. She ___ (go) home early.","a":["might have gone","may have gone","could have gone"]},{"r":"The photographer must have climbed the mountain."}],"advanced":[{"q":"Rewrite: 'I'm sure he used a filter.' → He ___ a filter.","a":["must have used"]},{"q":"Rewrite: 'It's impossible that she saw us.' → She ___ us.","a":["can't have seen","couldn't have seen"]},{"q":"Rewrite: 'Perhaps the photo was taken in Paris.' → The photo ___ in Paris.","a":["might have been taken","may have been taken","could have been taken"]},{"q":"Correct the mistake: 'He mustn't be the owner – he's too young.'","a":["He can't be the owner – he's too young.","He can't be the owner - he's too young."]},{"q":"Rewrite: 'I'm sure they are working on the exhibition now.' → They ___ on the exhibition.","a":["must be working"]},{"q":"Choose the best option: 'She knew all the answers. She ___ studied a lot.'","o":["must have","might be","can't have"],"a":0},{"q":"Which sentence is the LEAST certain?","o":["It must have been a mistake.","It could have been a mistake.","It can't have been a mistake."],"a":1},{"r":"The picture can't have been taken by a professional."}]}},{"id":"gerinf","title":"Verbs + -ing / to infinitive","short":"enjoy taking, decide to take, remember / stop / try","slides":[{"k":"title","h":"-ing or to infinitive?","sub":"Picture this: learning to take better photos","hook":"Do you enjoy taking photos? What would you like to learn to photograph?"},{"k":"table","h":"Verbs + -ing","cols":["Verb","Example"],"rows":[["enjoy, like, love, hate, don't mind","I enjoy taking close-ups of flowers."],["avoid, finish, keep, imagine, miss","Avoid using the flash in museums."],["suggest, recommend, can't stand","She suggested changing the angle."]],"note":"Also use -ing after prepositions: I'm interested in learning photography."},{"k":"table","h":"Verbs + to infinitive","cols":["Verb","Example"],"rows":[["want, would like, hope, plan, decide","She decided to shoot in black and white."],["agree, refuse, promise, offer, learn","He refused to delete the photo."],["manage, need, seem, expect, afford","We managed to find the perfect angle."]]},{"k":"text","h":"Verbs that change meaning","p":["Some verbs can take both forms but the meaning changes."],"ex":["I **remember taking** this shot by chance. (a memory)","**Remember to set up** the tripod! (don't forget)","She **stopped taking** photos. (she doesn't do it any more)","She **stopped to take** a photo of the sunset. (in order to)","**Try changing** the angle. (an experiment)","I **tried to keep** the subject in focus, but it moved. (an effort)"]},{"k":"context","h":"Grammar in context","kind":"Tips · Photography club","title":"Five tips for better photos","text":["1. **Avoid using** the flash – natural light is more pleasant.","2. **Try getting** closer to your subject. A close-up can have a big impact.","3. **Don't forget to check** the frame before you shoot.","4. **Keep practising** every day. Many great shots happen by chance!","5. **Remember to look** for things out of the ordinary. The viewer **will enjoy discovering** them."]},{"k":"mistakes","h":"Watch out!","items":[["I enjoy to take photos.","I enjoy taking photos.","enjoy + -ing."],["She decided entering the competition.","She decided to enter the competition.","decide + to infinitive."],["I'm good at edit photos.","I'm good at editing photos.","After a preposition, use -ing."]]},{"k":"check","q":"I can't afford ___ a new lens.","o":["buying","to buy","buy"],"a":1,"e":"afford + to infinitive."},{"k":"check","q":"We stopped ___ a photo of the sunset.","o":["to take","taking","take"],"a":0,"e":"We stopped in order to take a photo."},{"k":"sum","h":"Remember","p":["-ing after enjoy, avoid, finish, keep, mind, suggest and prepositions.","to + verb after want, decide, hope, plan, manage, refuse, promise.","remember / forget / stop / try change meaning."]}],"ex":{"basic":[{"q":"I enjoy ___ photos.","o":["taking","to take","take"],"a":0},{"q":"She wants ___ a photographer.","o":["to be","being","be"],"a":0},{"q":"Do you mind ___ (wait) a moment?","a":["waiting"]},{"q":"We hope ___ (visit) the exhibition.","a":["to visit"]},{"q":"He finished ___ (edit) the video.","a":["editing"]},{"q":"I'm interested in ___ about photography.","o":["learning","to learn","learn"],"a":0},{"r":"She decided to buy a new camera."},{"q":"They promised ___ (send) us the photos.","a":["to send"]}],"intermediate":[{"q":"Avoid ___ (use) the flash in museums.","a":["using"]},{"q":"We managed ___ (get) tickets for the exhibition.","a":["to get"]},{"q":"My teacher suggested ___ (shoot) in black and white.","a":["shooting"]},{"q":"I remember ___ my first camera. It was red.","o":["getting","to get","get"],"a":0},{"q":"Don't forget ___ the lens cap!","o":["to take off","taking off","take off"],"a":0},{"q":"He refused ___ (delete) the embarrassing photo.","a":["to delete"]},{"q":"Keep ___ (practise) and you'll get better.","a":["practising","practicing"]},{"r":"I can't stand posing for photos."}],"advanced":[{"q":"'He stopped to talk to me' means:","o":["He stopped walking in order to talk.","He doesn't talk to me any more.","He talked and then stopped."],"a":0},{"q":"Try ___ (change) the angle – it might look better.","a":["changing"]},{"q":"I tried ___ (open) the file but it was damaged.","a":["to open"]},{"q":"I'll never forget ___ (see) the northern lights.","a":["seeing"]},{"q":"Correct the mistake: 'She's thinking about to start a photo blog.'","a":["She's thinking about starting a photo blog.","She's thinking about starting a photo blog"]},{"q":"Choose the correct pair: 'I don't mind ___ but I refuse ___ in the photo.'","o":["helping / to appear","to help / appearing","help / appear"],"a":0},{"q":"Rewrite: 'Why don't we use a tripod?' → She suggested ___ a tripod.","a":["using"]},{"r":"Please remember to switch off your camera before the show."}]}}],"files":{"list":"downloads/unit4/vocabulary-list.pdf","vocab":{"basic":"downloads/unit4/vocabulary-basic.pdf","intermediate":"downloads/unit4/vocabulary-intermediate.pdf","advanced":"downloads/unit4/vocabulary-advanced.pdf"},"grammar":{"deduction":{"basic":"downloads/unit4/grammar-deduction-basic.pdf","intermediate":"downloads/unit4/grammar-deduction-intermediate.pdf","advanced":"downloads/unit4/grammar-deduction-advanced.pdf"},"gerinf":{"basic":"downloads/unit4/grammar-gerinf-basic.pdf","intermediate":"downloads/unit4/grammar-gerinf-intermediate.pdf","advanced":"downloads/unit4/grammar-gerinf-advanced.pdf"}}}},{"id":5,"title":"Survival","topic":"Survival skills, equipment and natural disasters","color":"#f26b00","vocab":[{"name":"Survival equipment","words":[["compass","noun","a tool with a needle that points north","brújula","Use a *compass* to find your way."],["first-aid kit","noun","a box with things to treat small injuries","botiquín","Always take a *first-aid kit* when you go hiking."],["magnifying glass","noun","a glass that makes things look bigger","lupa","You can start a fire with a *magnifying glass* and sunlight."],["matches","noun (pl)","small sticks that make fire when you rub them","cerillas","Keep the *matches* dry."],["metal pot","noun","a metal container for cooking or boiling water","olla de metal","We boiled water in a *metal pot*."],["multitool","noun","a small tool with a knife, scissors and other tools","multiherramienta","My *multitool* has a tiny saw."],["rope","noun","a long, thick string","cuerda","We used a *rope* to climb down."],["tarpaulin","noun","a large waterproof sheet","lona","A *tarpaulin* can make a quick shelter."],["torch","noun","a small electric light you can carry","linterna","Turn on the *torch* – it's dark in the cave."],["water purification tablets","noun (pl)","tablets that make dirty water safe to drink","pastillas potabilizadoras","Put *water purification tablets* in the river water."],["waterproof bag","noun","a bag that doesn't let water in","bolsa estanca","Keep your phone in a *waterproof bag*."],["whistle","noun","a small object you blow to make a loud sound","silbato","Blow the *whistle* if you get lost."]]},{"name":"Disasters","words":[["avalanche","noun","a large amount of snow falling down a mountain","avalancha, alud","The *avalanche* blocked the road."],["cyberattack","noun","an attack on computer systems","ciberataque","A *cyberattack* shut down the hospital's computers."],["drought","noun","a long period without rain","sequía","The *drought* destroyed the crops."],["earthquake","noun","a sudden shaking of the ground","terremoto","The *earthquake* damaged hundreds of buildings."],["flooding","noun","when water covers land that is usually dry","inundación","Heavy rain caused *flooding* in the town."],["forest fire","noun","a fire that spreads through a forest","incendio forestal","The *forest fire* burned for a week."],["global warming","noun","the increase in the Earth's temperature","calentamiento global","*Global warming* is melting glaciers."],["hurricane","noun","a violent storm with very strong winds","huracán","The *hurricane* hit the coast at night."],["nuclear explosion","noun","a huge explosion caused by nuclear energy","explosión nuclear","A *nuclear explosion* happened at Chernobyl in 1986."],["volcanic eruption","noun","when a volcano throws out lava and ash","erupción volcánica","The *volcanic eruption* in La Palma lasted 85 days."]]},{"name":"Extra: Survival skills","extra":true,"words":[["attitude","noun","your way of thinking about a situation","actitud","A positive *attitude* helps you survive."],["heat","noun","high temperature","calor","The *heat* in the desert is dangerous."],["protect","verb","to keep safe from harm","proteger","A hat *protects* you from the sun."],["source","noun","where something comes from","fuente","Find a *source* of clean water."],["task","noun","a piece of work you must do","tarea","Building a shelter is your first *task*."]]}],"grammar":[{"id":"cond012","title":"Zero, first and second conditional","short":"if and unless","slides":[{"k":"title","h":"Conditionals 0, 1 and 2","sub":"Survival: what would you do?","hook":"If you got lost in a forest with only a rope, a torch and a whistle, what would you do first?"},{"k":"table","h":"Three conditionals","cols":["Type","If clause","Result clause","Use"],"rows":[["Zero","if + present simple","present simple","General truths, facts"],["First","if + present simple","will / can / might + verb","Real, possible future situations"],["Second","if + past simple","would / could / might + verb","Imaginary or unlikely situations"]]},{"k":"text","h":"Zero conditional","p":["Things that are always true – facts of survival!"],"ex":["If you **heat** water in a metal pot, it **boils**.","If you **don't drink** water in the heat, you **get** dehydrated.","If you **point** a magnifying glass at the sun, it **can start** a fire."]},{"k":"text","h":"First conditional","p":["A real possibility in the future."],"ex":["If it **rains**, we**'ll put up** the tarpaulin.","If you **get** lost, **blow** your whistle!","We **won't find** the camp if we **don't take** a compass."]},{"k":"text","h":"Second conditional","p":["An imaginary or unlikely situation in the present or future.","With 'be', we often use 'were' for all persons: If I were you..."],"ex":["If I **were** on a desert island, I**'d build** a shelter with rope and a tarpaulin.","If we **had** matches, we **could make** a fire.","**If I were you**, I'd put the phone in a waterproof bag."]},{"k":"text","h":"unless = if ... not","p":["'Unless' means 'except if'. Don't use a negative verb after it."],"ex":["You'll get cold **unless** you **protect** yourself from the wind. (= if you don't protect)","**Unless** we **find** a source of clean water, we won't survive."]},{"k":"context","h":"Grammar in context","kind":"Survival guide · Disasters","title":"What to do in an earthquake","text":["If the ground **starts** to shake, **get** under a strong table. If you **are** outside, **move** away from buildings.","Keep a first-aid kit and a torch at home. If there **is** an earthquake at night, you**'ll need** them.","Don't use the lift **unless** it **is** safe. And remember: if everyone **stayed** calm, fewer people **would get** hurt."]},{"k":"mistakes","h":"Watch out!","items":[["If there will be an earthquake, get under a table.","If there is an earthquake, get under a table.","No 'will' in the if clause."],["If I would have a compass, I'd know the way.","If I had a compass, I'd know the way.","No 'would' in the if clause."],["Unless you don't take water, you'll get thirsty.","Unless you take water, you'll get thirsty.","'unless' already contains 'not'."]]},{"k":"check","q":"If I ___ a bear in the forest, I would stay very still.","o":["see","saw","will see"],"a":1,"e":"Imaginary situation → second conditional: if + past simple."},{"k":"check","q":"We'll get wet ___ we put up the tarpaulin.","o":["if","unless","when"],"a":1,"e":"= if we don't put up the tarpaulin."},{"k":"sum","h":"Remember","p":["0: if + present, present (facts).","1: if + present, will (real future).","2: if + past, would (imaginary).","unless = if not. No will / would after if."]}],"ex":{"basic":[{"q":"If you heat ice, it ___ .","o":["melts","would melt","melted"],"a":0},{"q":"If it rains, we ___ (stay) in the tent.","a":["will stay","'ll stay"]},{"q":"If I ___ (have) a million euros, I'd travel the world.","a":["had"]},{"q":"If you get lost, ___ your whistle.","o":["blow","blew","would blow"],"a":0},{"q":"If I were you, I ___ take a torch.","o":["would","will","am"],"a":0},{"q":"We won't go ___ the weather is good.","o":["unless","if","when"],"a":0},{"r":"If we find water we will survive."},{"q":"Plants die if they ___ (not / get) water.","a":["don't get","do not get"]}],"intermediate":[{"q":"If I ___ (be) on a desert island, I ___ (build) a raft.","a":["were / would build","was / would build","were / 'd build","was / 'd build"],"h":"Write both verbs separated by /"},{"q":"Unless we ___ (leave) now, it'll get dark.","a":["leave"]},{"q":"If you ___ (not / boil) the water, you'll get ill.","a":["don't boil","do not boil"]},{"q":"What ___ you do if you saw a shark?","o":["would","will","did"],"a":0},{"q":"If there's an earthquake, ___ under a table.","o":["get","you'd get","got"],"a":0},{"q":"We could make a fire if we ___ some matches.","o":["had","have","would have"],"a":0},{"q":"Rewrite with unless: 'If you don't take a map, you'll get lost.' → You'll get lost ___ a map.","a":["unless you take"]},{"r":"What would you take if you could only carry three things?"}],"advanced":[{"q":"Correct the mistake: 'If I would know the way, I would tell you.'","a":["If I knew the way, I would tell you.","If I knew the way, I'd tell you."]},{"q":"Which sentence is about an unlikely situation?","o":["If it snows, we'll go skiing.","If it snowed in Seville, people would be shocked.","If it snows, roads close."],"a":1},{"q":"Rewrite: 'I don't have a compass, so I can't find north.' → If I ___ a compass, I ___ north.","a":["had / could find","had / would find"],"h":"Write both parts separated by /"},{"q":"Rewrite: 'Unless you hurry, you'll miss the rescue boat.' → If you ___ , you'll miss the rescue boat.","a":["don't hurry","do not hurry"]},{"q":"If the volcano ___ (erupt) again, the authorities ___ (evacuate) the town. (real possibility)","a":["erupts / will evacuate","erupts / 'll evacuate"],"h":"Write both verbs separated by /"},{"q":"Choose the best advice: 'If I were you, I ___ alone.'","o":["wouldn't go","won't go","don't go"],"a":0},{"q":"Complete: 'If people ___ (use) less energy, global warming ___ (slow) down.' (imaginary)","a":["used / would slow","used / 'd slow"],"h":"Write both verbs separated by /"},{"r":"If I were stuck in a lift I wouldn't panic."}]}},{"id":"cond3","title":"Third conditional, I wish / If only","short":"Imagining the past and expressing regrets","slides":[{"k":"title","h":"Third conditional & wishes","sub":"Survival: lessons from real disasters","hook":"Think of a disaster you know about (a hurricane, a forest fire, a volcanic eruption). What could people have done differently?"},{"k":"table","h":"Third conditional","cols":["If clause","Result clause"],"rows":[["If + past perfect (had + participle)","would / could / might have + participle"],["If they had checked the forecast,","they wouldn't have been caught in the avalanche."],["If we had taken a compass,","we could have found the path."]],"note":"It's about an imaginary past: the opposite of what really happened."},{"k":"text","h":"Real past vs imaginary past","p":["Reality: They didn't bring a torch, so they got lost in the dark.","Imaginary past: If they **had brought** a torch, they **wouldn't have got** lost."],"ex":["If the alarm **had worked**, people **would have left** before the flooding.","She **might have survived** the hurricane if she **had stayed** inside."]},{"k":"text","h":"What if...?","p":["We use 'What if...?' to imagine possible situations, past or future."],"ex":["**What if** the volcanic eruption starts tonight?","**What if** we **hadn't packed** the first-aid kit?"]},{"k":"table","h":"I wish / If only","cols":["Wish about...","Form","Example"],"rows":[["the present","wish / if only + past simple","I wish I had a torch. (I don't)"],["the past (regret)","wish / if only + past perfect","If only we had brought the water purification tablets!"],["annoying behaviour","wish + would","I wish you would stop complaining about the heat!"]]},{"k":"context","h":"Grammar in context","kind":"True story · Survival","title":"Lost in the mountains","text":["Two hikers got lost in the Pyrenees last winter. 'If only we **had checked** the weather!' says Pablo. 'If we **had seen** the forecast, we **wouldn't have gone** up.'","Luckily, they had a whistle and a compass. 'If we **hadn't had** the whistle, the rescue team **wouldn't have found** us.'","'Now I wish I **knew** more about first aid. What if one of us **had been** injured?'"]},{"k":"mistakes","h":"Watch out!","items":[["If I would have known about the flooding, I would have left.","If I had known about the flooding, I would have left.","Past perfect in the if clause."],["I wish I have more water.","I wish I had more water.","Present wish → past simple."],["If only I didn't forget the matches yesterday.","If only I hadn't forgotten the matches yesterday.","Past regret → past perfect."]]},{"k":"check","q":"If we ___ the forecast, we wouldn't have been caught in the avalanche.","o":["had checked","checked","would check"],"a":0,"e":"Third conditional: if + past perfect."},{"k":"check","q":"It's so dark. I wish I ___ a torch.","o":["have","had","would have"],"a":1,"e":"Wish about the present → past simple."},{"k":"sum","h":"Remember","p":["Third conditional: if + had done, would have done.","wish / if only + past simple → present.","wish / if only + past perfect → past regrets.","What if...? → imagining possibilities."]}],"ex":{"basic":[{"q":"If I had studied, I ___ passed.","o":["would have","will have","would"],"a":0},{"q":"If she ___ (leave) earlier, she wouldn't have missed the train.","a":["had left","'d left"]},{"q":"I wish I ___ (have) a map right now.","a":["had"]},{"q":"If only I ___ my phone at home yesterday!","o":["hadn't left","didn't leave","don't leave"],"a":0},{"q":"We ___ (not / get) lost if we had taken a compass.","a":["wouldn't have got","would not have got","wouldn't have gotten"]},{"q":"I wish it ___ so hot today.","o":["wasn't","isn't","hadn't been"],"a":0},{"r":"If we had brought a torch we would have seen the path."},{"q":"___ if the boat doesn't come?","o":["What","Who","Why"],"a":0}],"intermediate":[{"q":"If they ___ (listen) to the warning, they ___ (be) safe.","a":["had listened / would have been","'d listened / would have been"],"h":"Write both verbs separated by /"},{"q":"I wish I ___ (not / eat) all the chocolate yesterday.","a":["hadn't eaten","had not eaten"]},{"q":"If only I ___ (can) swim better!","a":["could"]},{"q":"She might have survived if she ___ calm.","o":["had stayed","stayed","would stay"],"a":0},{"q":"I wish my brother ___ stop playing loud music!","o":["would","will","had"],"a":0},{"q":"Reality: 'I didn't bring a coat, so I was cold.' → If I ___ a coat, I wouldn't have been cold.","a":["had brought","'d brought"]},{"q":"If the rescue team ___ (not / find) us, we ___ (die).","a":["hadn't found / would have died","had not found / would have died"],"h":"Write both verbs separated by /"},{"r":"I wish I had packed more food."}],"advanced":[{"q":"Rewrite: 'We didn't see the sign, so we went the wrong way.' → If we ___ the sign, we ___ the wrong way.","a":["had seen / wouldn't have gone","'d seen / wouldn't have gone","had seen / would not have gone"],"h":"Write both parts separated by /"},{"q":"Rewrite: 'I regret not learning first aid.' → I wish ___ first aid.","a":["I had learnt","I had learned","I'd learnt","I'd learned"]},{"q":"Rewrite: 'It's a pity I'm not braver.' → If only ___ braver.","a":["I were","I was"]},{"q":"Correct the mistake: 'If the alarm would have rung, we would have escaped.'","a":["If the alarm had rung, we would have escaped.","If the alarm had rung, we'd have escaped."]},{"q":"Which sentence expresses annoyance?","o":["I wish you had told me.","I wish you would stop shouting.","I wish I were taller."],"a":1},{"q":"Complete the mixed idea: 'If I had slept more last night, I ___ (not / be) so tired now.'","a":["wouldn't be","would not be"]},{"q":"Choose: 'What if we ___ the tablets? We'd have been ill!'","o":["hadn't had","don't have","won't have"],"a":0},{"r":"If only we had checked the weather before we left."}]}}],"files":{"list":"downloads/unit5/vocabulary-list.pdf","vocab":{"basic":"downloads/unit5/vocabulary-basic.pdf","intermediate":"downloads/unit5/vocabulary-intermediate.pdf","advanced":"downloads/unit5/vocabulary-advanced.pdf"},"grammar":{"cond012":{"basic":"downloads/unit5/grammar-cond012-basic.pdf","intermediate":"downloads/unit5/grammar-cond012-intermediate.pdf","advanced":"downloads/unit5/grammar-cond012-advanced.pdf"},"cond3":{"basic":"downloads/unit5/grammar-cond3-basic.pdf","intermediate":"downloads/unit5/grammar-cond3-intermediate.pdf","advanced":"downloads/unit5/grammar-cond3-advanced.pdf"}}}},{"id":6,"title":"News travels fast","topic":"News, media and how to spot fake stories","color":"#e5243b","vocab":[{"name":"News and media","words":[["breaking news","noun","news about something that is happening right now","noticia de última hora","*Breaking news*: a storm has hit the coast."],["eyewitness","noun","a person who saw an event happen","testigo presencial","An *eyewitness* filmed the accident on her phone."],["headline","noun","the title of a news story","titular","The *headline* said 'Teen saves dog from river'."],["journalist","noun","a person who writes or reports the news","periodista","The *journalist* interviewed the mayor."],["live","adj / adv","broadcast at the same time as it happens","en directo","They showed the match *live* on TV."],["news presenter","noun","a person who reads the news on TV or radio","presentador/a de noticias","The *news presenter* smiled and said good evening."],["report","noun / verb","an account of an event; to tell people about it","reportaje / informar","She wrote a *report* about the protest."],["reporter","noun","a journalist who goes to places to collect news","reportero/a","The *reporter* is standing outside the stadium."],["source","noun","a person or document that gives information","fuente","Always check the *source* of a story."],["update","noun / verb","the newest information about something","actualización / actualizar","We'll give you an *update* in an hour."]]},{"name":"Compound nouns: media","words":[["celebrity influencer","noun","a famous person who affects what followers buy or think","influencer famoso/a","A *celebrity influencer* posted about the new trainers."],["clickbait","noun","online content designed to make you click","ciberanzuelo, clickbait","'You won't believe what happened next!' is typical *clickbait*."],["conspiracy theory","noun","a belief that a secret group is behind an event","teoría de la conspiración","There's a *conspiracy theory* that the moon landing was fake."],["current affairs","noun (pl)","important political and social events happening now","actualidad","We discuss *current affairs* in class every Monday."],["fake news","noun","false stories that look like real news","noticias falsas, bulos","*Fake news* spreads quickly on social media."],["media outlet","noun","a company that publishes news (newspaper, channel, website)","medio de comunicación","Which *media outlet* published the story first?"],["newsfeed","noun","a list of updates on a social media app","muro, feed de noticias","My *newsfeed* is full of football videos."],["paywall","noun","a system that makes you pay to read content online","muro de pago","I couldn't read the article because of the *paywall*."],["social media platform","noun","a website or app for sharing content","red social, plataforma","TikTok is a popular *social media platform*."],["visual medium","noun","a way of communicating with images","medio visual","Instagram is mainly a *visual medium*."]]},{"name":"Extra: Adverb + adjective collocations","extra":true,"words":[["absolutely delighted","collocation","extremely happy","absolutamente encantado/a","She was *absolutely delighted* with the prize."],["completely different","collocation","not similar at all","completamente diferente","The real story was *completely different*."],["highly unlikely","collocation","very improbable","muy improbable","It's *highly unlikely* that aliens built the pyramids."],["incredibly weird","collocation","very strange","increíblemente raro/a","That video was *incredibly weird*."],["ridiculously easy","collocation","extremely easy","ridículamente fácil","The quiz was *ridiculously easy*."],["extremely friendly","collocation","very kind and nice","extremadamente amable","The reporter was *extremely friendly*."]]}],"grammar":[{"id":"reported","title":"Reported speech","short":"Reporting what people said","slides":[{"k":"title","h":"Reported speech","sub":"News travels fast: what did the eyewitness say?","hook":"Think of a piece of breaking news you heard recently. Who said it? Can you report what they said?"},{"k":"text","h":"Direct and reported speech","p":["Direct speech repeats the exact words. Reported speech tells someone what another person said, usually with 'said' or 'told'. Journalists use it all the time!"],"ex":["Direct: 'I **saw** the fire,' the eyewitness said.","Reported: The eyewitness said that she **had seen** the fire."]},{"k":"table","h":"Tenses move back","cols":["Direct speech","Reported speech"],"rows":[["present simple: 'I work for a big media outlet.'","past simple: He said he worked for a big media outlet."],["present continuous: 'I'm reporting live.'","past continuous: She said she was reporting live."],["past simple: 'I saw the accident.'","past perfect: He said he had seen the accident."],["present perfect: 'We've published an update.'","past perfect: They said they had published an update."],["will: 'The story will be the main headline.'","would: She said the story would be the main headline."],["can: 'I can check the source.'","could: He said he could check the source."]]},{"k":"table","h":"Other changes","cols":["Direct","Reported"],"rows":[["now","then"],["today","that day"],["tomorrow","the next day / the following day"],["yesterday","the day before / the previous day"],["here","there"],["this","that"]],"note":"Pronouns change too: 'I'm a journalist,' Ana said → Ana said she was a journalist."},{"k":"text","h":"say or tell?","p":["say + (that) + clause: He said (that) it was fake news.","tell + person + (that) + clause: He told me (that) it was fake news."],"ex":["The news presenter **said** the story was clickbait.","The news presenter **told us** the story was clickbait."]},{"k":"context","h":"Grammar in context","kind":"News report · Breaking news","title":"Fire at the shopping centre","text":["An eyewitness **told** our reporter that she **had seen** smoke at about 6 p.m. She **said** that people **were running** out of the building.","A firefighter **said** that nobody **had been** hurt. He **told** journalists that they **would give** an update the next day.","The mayor **said** that the centre **could** open again that week. Some social media posts claimed it was an attack, but that was fake news."]},{"k":"mistakes","h":"Watch out!","items":[["The reporter said me that the road was closed.","The reporter told me that the road was closed.","tell + person; say without person."],["He told that the headline was wrong.","He said that the headline was wrong.","tell needs an object (me / us / them)."],["They said they will publish the story tomorrow.","They said they would publish the story the next day.","will → would; tomorrow → the next day."]]},{"k":"check","q":"'I am watching the breaking news.' → He said he ___ the breaking news.","o":["is watching","was watching","watched"],"a":1,"e":"Present continuous → past continuous."},{"k":"check","q":"'We have published the headline.' → They said they ___ the headline.","o":["had published","have published","published"],"a":0,"e":"Present perfect → past perfect."},{"k":"sum","h":"Remember","p":["Tenses move one step back into the past.","Change pronouns and time/place words.","say something / tell someone something.","'that' is optional after say and tell."]}],"ex":{"basic":[{"q":"'I am a journalist.' → She said she ___ a journalist.","o":["was","is","has been"],"a":0},{"q":"'I like the news.' → He said he ___ (like) the news.","a":["liked"]},{"q":"She ___ me that the headline was wrong.","o":["told","said","says"],"a":0},{"q":"He ___ that the video was fake.","o":["said","told","told to"],"a":0},{"q":"'I can't hear you.' → She said she ___ hear me.","a":["couldn't","could not"]},{"q":"'We will call you.' → They said they ___ call me.","a":["would"]},{"r":"The reporter said that the road was closed."},{"q":"'I'm tired.' → Leo said ___ was tired.","o":["he","I","you"],"a":0}],"intermediate":[{"q":"'I saw the accident.' → The eyewitness said she ___ the accident.","a":["had seen","'d seen"]},{"q":"'We're filming now.' → They said they were filming ___ .","o":["then","now","today"],"a":0},{"q":"'I'll post it tomorrow.' → She said she would post it ___ .","o":["the next day","tomorrow","yesterday"],"a":0},{"q":"'I've read the article.' → He said he ___ the article.","a":["had read","'d read"]},{"q":"'The story is true.' → The journalist told ___ the story was true.","o":["us","to us","for us"],"a":0},{"q":"'I'm writing a report.' → Marta said she ___ a report.","a":["was writing"]},{"q":"'I met him yesterday.' → She said she had met him ___ .","a":["the day before","the previous day"]},{"r":"He told me that he had never been on TV."}],"advanced":[{"q":"Report: 'I can't find a reliable source,' said the student.","a":["The student said he couldn't find a reliable source.","The student said she couldn't find a reliable source.","The student said that he couldn't find a reliable source.","The student said that she couldn't find a reliable source.","The student said they couldn't find a reliable source."]},{"q":"Report: 'We will update the story this evening,' the editor told us. → The editor told us they ___ the story that evening.","a":["would update"]},{"q":"Correct the mistake: 'She said me the news was fake.'","a":["She told me the news was fake.","She told me that the news was fake.","She said the news was fake.","She said that the news was fake."]},{"q":"Report: 'This photo was taken here,' he said. → He said that ___ photo had been taken ___ .","a":["that / there"],"h":"Write both words separated by /"},{"q":"Report: 'I have been working on this story for months,' she said. → She said she ___ on that story for months.","a":["had been working"]},{"q":"Which reported sentence is correct for: 'I must leave now.'?","o":["He said he had to leave then.","He said he must to leave now.","He told he had to leave."],"a":0},{"q":"Report: 'I didn't write that headline,' the journalist said. → The journalist said he ___ that headline.","a":["hadn't written","had not written"]},{"r":"The presenter told the viewers that the match would be shown live."}]}},{"id":"repquest","title":"Reported questions, requests and commands","short":"asked if..., told me to..., asked me not to...","slides":[{"k":"title","h":"Reported questions & commands","sub":"News travels fast: the interview","hook":"If you could interview a famous news presenter or influencer, what would you ask them?"},{"k":"text","h":"Reported yes/no questions","p":["Use asked + if / whether + statement word order. No question mark, no do / does / did."],"ex":["'Are you a reporter?' → She asked me **if I was** a reporter.","'Did you see the accident?' → The police asked the eyewitness **whether she had seen** the accident."]},{"k":"text","h":"Reported wh- questions","p":["Use asked + question word + statement word order."],"ex":["'Where do you get your news?' → He asked me **where I got** my news.","'What happened?' → The journalist asked **what had happened**.","'Why did you share that post?' → My teacher asked **why I had shared** that post."]},{"k":"table","h":"Requests and commands","cols":["Direct","Reported"],"rows":[["'Please check your sources.'","The teacher asked us to check our sources."],["'Don't share fake news!'","She told us not to share fake news."],["'Turn off your newsfeed for an hour.'","He told me to turn off my newsfeed for an hour."]],"note":"asked / told + person + (not) to + infinitive."},{"k":"context","h":"Grammar in context","kind":"School newspaper · Interview","title":"We met a news presenter!","text":["Last week we interviewed Clara Ruiz, a news presenter on local TV. First, we **asked her how** she **had become** a journalist. She said she had started on the school newspaper!","Then Leo **asked whether** she **was** nervous when she was live on TV. She laughed and said 'Always!'","At the end, she **told us to read** news from different sources and **asked us not to believe** every headline on social media."]},{"k":"mistakes","h":"Watch out!","items":[["She asked me where did I get my news.","She asked me where I got my news.","Statement word order, no 'did'."],["He asked me was the story true.","He asked me if the story was true.","Yes/no questions need if / whether."],["She told me don't click on the clickbait.","She told me not to click on the clickbait.","Negative command: not to + infinitive."]]},{"k":"check","q":"'Can you send me the update?' → The editor asked ___ send her the update.","o":["if I could","could I","me can"],"a":0,"e":"Yes/no question → if + statement order."},{"k":"check","q":"'Don't believe everything on your newsfeed!' → Mum told me ___ everything on my newsfeed.","o":["don't believe","not to believe","to not believing"],"a":1,"e":"Negative command → not to + infinitive."},{"k":"sum","h":"Remember","p":["Yes/no → asked if / whether + statement.","Wh- → asked + wh- word + statement.","Requests → asked someone to do.","Commands → told someone (not) to do."]}],"ex":{"basic":[{"q":"'Are you OK?' → She asked me ___ I was OK.","o":["if","that","what"],"a":0},{"q":"'Where do you live?' → He asked me where I ___ .","o":["lived","did live","live do"],"a":0},{"q":"'Sit down.' → The teacher told us ___ down.","o":["to sit","sit","sitting"],"a":0},{"q":"'Don't run!' → She told us ___ run.","a":["not to"]},{"q":"'Please help me.' → He asked me ___ him.","a":["to help"]},{"q":"'What's your name?' → She asked me what my name ___ .","a":["was"]},{"r":"The reporter asked me where I was from."},{"q":"'Do you like the news?' → He asked ___ I liked the news.","o":["whether","that","do"],"a":0}],"intermediate":[{"q":"'Did you see the match?' → She asked me if I ___ the match.","a":["had seen","'d seen"]},{"q":"'Why are you late?' → The teacher asked me why I ___ late.","a":["was"]},{"q":"'Please don't post that photo.' → My friend asked me ___ that photo.","a":["not to post"]},{"q":"'Can you call me later?' → She asked me ___ call her later.","o":["if I could","could I","can I"],"a":0},{"q":"'Check your sources!' → The journalist told us ___ our sources.","a":["to check"]},{"q":"'How long have you been a presenter?' → I asked her how long she ___ a presenter.","a":["had been"]},{"q":"'Will you be on TV?' → They asked if I ___ be on TV.","a":["would"]},{"r":"He asked us not to share the video."}],"advanced":[{"q":"Report: 'Where did you find this story?' the editor asked me.","a":["The editor asked me where I had found that story.","The editor asked me where I had found this story."]},{"q":"Report: 'Are you going to publish it?' she asked them.","a":["She asked them if they were going to publish it.","She asked them whether they were going to publish it."]},{"q":"Report: 'Don't believe everything you read,' my grandad told me.","a":["My grandad told me not to believe everything I read."]},{"q":"Correct the mistake: 'She asked me what was I doing.'","a":["She asked me what I was doing.","She asked me what I was doing"]},{"q":"Report: 'Could you speak more slowly, please?' I asked the presenter. → I asked the presenter ___ more slowly.","a":["to speak"]},{"q":"Which is correct for: 'Who wrote the article?'","o":["She asked who had written the article.","She asked who did write the article.","She asked who the article had written."],"a":0},{"q":"Report: 'What will happen next?' the viewers asked. → The viewers asked what ___ next.","a":["would happen"]},{"r":"The police asked the eyewitness if she had taken any photos."}]}}],"files":{"list":"downloads/unit6/vocabulary-list.pdf","vocab":{"basic":"downloads/unit6/vocabulary-basic.pdf","intermediate":"downloads/unit6/vocabulary-intermediate.pdf","advanced":"downloads/unit6/vocabulary-advanced.pdf"},"grammar":{"reported":{"basic":"downloads/unit6/grammar-reported-basic.pdf","intermediate":"downloads/unit6/grammar-reported-intermediate.pdf","advanced":"downloads/unit6/grammar-reported-advanced.pdf"},"repquest":{"basic":"downloads/unit6/grammar-repquest-basic.pdf","intermediate":"downloads/unit6/grammar-repquest-intermediate.pdf","advanced":"downloads/unit6/grammar-repquest-advanced.pdf"}}}},{"id":7,"title":"Future living","topic":"Technology, smart cities and the buildings of the future","color":"#00a3a3","vocab":[{"name":"Adjectives to describe technology","words":[["adaptable","adj","able to change to suit different situations","adaptable","This *adaptable* furniture changes from a bed into a desk."],["affordable","adj","cheap enough for most people to buy","asequible","Solar panels are more *affordable* than before."],["energy-saving","adj","using less electricity","de bajo consumo","We have *energy-saving* light bulbs at home."],["experimental","adj","new and still being tested","experimental","The flying taxi is still *experimental*."],["high-tech","adj","using very modern technology","de alta tecnología","The new hospital is very *high-tech*."],["innovative","adj","using new and original ideas","innovador/a","It's an *innovative* way to recycle water."],["inspiring","adj","making you want to do something","inspirador/a","Her talk about green cities was *inspiring*."],["smart","adj","connected to the internet and able to work automatically","inteligente","A *smart* fridge tells you when milk runs out."],["solar-powered","adj","working with energy from the sun","que funciona con energía solar","We charged our phones with a *solar-powered* charger."],["virtual","adj","created by computers, not physically real","virtual","We took a *virtual* tour of the museum."]]},{"name":"Buildings and materials","words":[["brick","noun","a rectangular block of baked clay used to build walls","ladrillo","The old school is made of red *brick*."],["concrete","noun","a hard building material made of cement, sand and water","hormigón","*Concrete* produces a lot of CO2."],["hut","noun","a small simple building","cabaña, choza","The shepherds slept in a stone *hut*."],["iron","noun","a strong, hard metal","hierro","The Eiffel Tower is made of *iron*."],["mud","noun","wet earth","barro","Some houses in Africa are built with *mud*."],["skyscraper","noun","a very tall building","rascacielos","Dubai has the tallest *skyscraper* in the world."],["steel","noun","a very strong metal made from iron","acero","Modern bridges are made of *steel*."],["stone","noun","hard natural material from the ground","piedra","The castle walls are made of *stone*."],["storey","noun","a level of a building","planta, piso","Our block of flats has ten *storeys*."],["tent","noun","a shelter made of cloth that you can carry","tienda de campaña","We slept in a *tent* at the festival."],["tower","noun","a tall narrow building or part of a building","torre","You can see the whole city from the *tower*."]]},{"name":"Extra: Computing and AI","extra":true,"words":[["automated","adj","done by machines, not people","automatizado/a","The car park is fully *automated*."],["block","verb","to stop something from happening or getting through","bloquear","This app *blocks* spam messages."],["bot","noun","a computer program that does tasks automatically","bot","A *bot* answered my question on the website."],["detect","verb","to notice or discover something","detectar","Sensors *detect* when you enter the room."],["simulate","verb","to copy how something works, often on a computer","simular","Pilots use computers to *simulate* flights."],["software","noun","programs used by a computer","software","Update the *software* on your laptop."]]}],"grammar":[{"id":"passive","title":"The passive","short":"Present, past and future passive","slides":[{"k":"title","h":"The passive","sub":"Future living: how smart cities are built","hook":"What materials are skyscrapers made of? Who designs smart buildings – and does it matter?"},{"k":"text","h":"Active or passive?","p":["In the passive, the focus is on the action or the object, not on who does it.","Use 'by' if you want to say who does the action."],"ex":["Active: Engineers **design** energy-saving buildings.","Passive: Energy-saving buildings **are designed** (by engineers)."]},{"k":"table","h":"Form: be + past participle","cols":["Tense","Passive form","Example"],"rows":[["Present simple","am / is / are + participle","Solar panels are installed on the roof."],["Past simple","was / were + participle","The Eiffel Tower was built of iron in 1889."],["Future (will)","will be + participle","Homes will be powered by the sun."],["Present continuous","am / is / are being + participle","A new skyscraper is being built."],["Present perfect","has / have been + participle","The software has been updated."]]},{"k":"text","h":"When do we use it?","p":["When we don't know who did it, when it isn't important, or when it's obvious.","It's very common in news, science and descriptions of technology."],"ex":["Concrete **is made** from cement, sand and water.","The first smart house **was designed** in the 1980s.","In the future, buildings **will be printed** by 3D printers."]},{"k":"table","h":"Negatives and questions","cols":["","Example"],"rows":[["−","The tower wasn't finished on time."],["?","Was the hut made of mud or stone?"],["?","When will the new solar-powered station be opened?"]]},{"k":"context","h":"Grammar in context","kind":"News · Smart cities","title":"The city that thinks","text":["In the new district, every building **is connected** to the internet. Lights **are switched** off automatically when nobody is in the room, and rubbish **is collected** by robots.","The first towers **were built** with steel and recycled concrete in 2024. More homes **are being built** right now.","By 2030, all the buses **will be powered** by solar energy, and traffic **will be controlled** by smart software."]},{"k":"mistakes","h":"Watch out!","items":[["The skyscraper built in 1931.","The skyscraper was built in 1931.","Don't forget the verb 'be'."],["The tower was design by a woman.","The tower was designed by a woman.","Use the past participle."],["The bus will be drive by a robot.","The bus will be driven by a robot.","Irregular participle: drive → driven."]]},{"k":"check","q":"Millions of energy-saving bulbs ___ every year.","o":["sell","are sold","were sell"],"a":1,"e":"Present simple passive: are + participle."},{"k":"check","q":"In the future, most houses ___ with 3D printers.","o":["will build","will be built","are building"],"a":1,"e":"Future passive: will be + participle."},{"k":"sum","h":"Remember","p":["Passive = be (in the right tense) + past participle.","Use 'by' to say who did it (only if important).","Common in news, science and descriptions of processes."]}],"ex":{"basic":[{"q":"English ___ all over the world.","o":["is spoken","speaks","is speak"],"a":0},{"q":"This bridge ___ (build) in 1990.","a":["was built"]},{"q":"The emails ___ (send) every morning. (present)","a":["are sent"]},{"q":"The new school ___ next year.","o":["will be opened","will open by","is opened yesterday"],"a":0},{"q":"The pyramids ___ by the Egyptians.","o":["were built","built","are build"],"a":0},{"q":"Smart phones ___ (make) in many countries.","a":["are made"]},{"r":"The house was made of wood."},{"q":"The tower ___ (not / finish) yet. It will be ready in May.","a":["isn't finished","is not finished","hasn't been finished"]}],"intermediate":[{"q":"The first skyscraper ___ (design) in Chicago in 1885.","a":["was designed"]},{"q":"Electricity ___ (produce) by the solar panels on the roof.","a":["is produced"]},{"q":"In 2040, deliveries ___ (make) by drones.","a":["will be made"]},{"q":"___ the hut made of mud or stone?","o":["Was","Did","Has"],"a":0},{"q":"Passive: 'A robot cleans the streets.' → The streets ___ by a robot.","a":["are cleaned"]},{"q":"Passive: 'They didn't use steel.' → Steel ___ .","a":["wasn't used","was not used"]},{"q":"A new metro line ___ at the moment.","o":["is being built","is built","was building"],"a":0},{"r":"The software will be updated tonight."}],"advanced":[{"q":"Passive: 'Engineers will test the experimental car next week.'","a":["The experimental car will be tested by engineers next week.","The experimental car will be tested next week.","The experimental car will be tested by engineers next week"]},{"q":"Passive: 'Someone has hacked the system.'","a":["The system has been hacked.","The system has been hacked"]},{"q":"Passive: 'They are installing sensors in every room.'","a":["Sensors are being installed in every room.","Sensors are being installed in every room"]},{"q":"Correct the mistake: 'The Sagrada Família was began in 1882.'","a":["The Sagrada Família was begun in 1882.","The Sagrada Familia was begun in 1882.","The Sagrada Família was started in 1882.","The Sagrada Familia was started in 1882."]},{"q":"Make a question: 'When / the Eiffel Tower / build?'","a":["When was the Eiffel Tower built?","When was the Eiffel Tower built"]},{"q":"Which sentence does NOT need 'by + agent'?","o":["Guernica was painted by Picasso.","My bike was stolen by someone.","The app was created by two teenagers."],"a":1},{"q":"By 2030, the old factory ___ (transform) into flats. (future)","a":["will be transformed","will have been transformed"]},{"r":"Most of the work will be done by automated machines."}]}},{"id":"quantifiers","title":"Quantifiers","short":"(not) enough, (a) few, (a) little, a lot of, plenty of, too much / many","slides":[{"k":"title","h":"Quantifiers","sub":"Future living: is there enough space in your city?","hook":"Does your town have enough green spaces? Are there too many cars? What about affordable homes?"},{"k":"table","h":"Countable or uncountable?","cols":["Quantifier","Countable (towers, bikes)","Uncountable (energy, space)"],"rows":[["a lot of / lots of","✓ a lot of skyscrapers","✓ a lot of concrete"],["plenty of (more than enough)","✓ plenty of solar panels","✓ plenty of space"],["many / few / a few","✓ a few towers","✗"],["much / little / a little","✗","✓ a little energy"],["too many / too much","✓ too many cars","✓ too much noise"],["(not) enough","✓ enough charging points","✓ enough steel"]]},{"k":"text","h":"a few / a little vs few / little","p":["'a few' and 'a little' are positive: some, a small amount.","'few' and 'little' (without 'a') are negative: almost none, not enough."],"ex":["There are **a few** smart buildings in my town. (some – good)","There are **few** affordable flats in the centre. (almost none – bad)","We need **a little** more energy to charge the car.","There's **little** space for new parks."]},{"k":"text","h":"too and enough","p":["too much / too many + noun = more than we want.","enough + noun = the right amount. not enough = less than we need.","With adjectives: too + adjective, adjective + enough."],"ex":["There's **too much** concrete and **too many** cars.","We don't have **enough** green, energy-saving homes.","The flat isn't **big enough**. And it's **too expensive** – not affordable at all."]},{"k":"context","h":"Grammar in context","kind":"Proposal · My neighbourhood","title":"How to improve our streets","text":["In our neighbourhood there are **too many** cars and **too much** noise. There are **very few** trees and **not enough** places for teenagers to hang out.","We propose an innovative plan: **plenty of** cycle lanes, **a few** solar-powered bus stops and **a lot of** green roofs.","It isn't **too expensive**. With **a little** help from the council, it could be ready in two years."]},{"k":"mistakes","h":"Watch out!","items":[["There are too much skyscrapers here.","There are too many skyscrapers here.","skyscrapers is countable → many."],["We haven't got space enough.","We haven't got enough space.","enough goes BEFORE a noun."],["The phone isn't enough smart.","The phone isn't smart enough.","enough goes AFTER an adjective."]]},{"k":"check","q":"There isn't ___ space for a new park.","o":["many","enough","few"],"a":1,"e":"space is uncountable; 'not enough' = less than we need."},{"k":"check","q":"Don't worry, the solar panels produce ___ energy for the whole building.","o":["plenty of","too few","many"],"a":0,"e":"plenty of = more than enough."},{"k":"sum","h":"Remember","p":["many / few + countable; much / little + uncountable.","a lot of, plenty of, enough + both.","a few / a little = some; few / little = not enough.","noun: enough steel; adjective: strong enough."]}],"ex":{"basic":[{"q":"There are ___ cars in the city centre.","o":["too many","too much","a little"],"a":0},{"q":"I have ___ money – I can buy a coffee.","o":["a little","a few","many"],"a":0},{"q":"There's too ___ noise in this street.","a":["much"]},{"q":"We have ___ friends in this town – about four.","o":["a few","a little","much"],"a":0},{"q":"There isn't ___ bread for everyone.","o":["enough","many","few"],"a":0},{"q":"We've got ___ of time – the film starts in two hours.","o":["plenty","few","many"],"a":0},{"r":"There are a lot of skyscrapers in New York."},{"q":"There's ___ light in this room. I can't see!","o":["too little","too many","a few"],"a":0}],"intermediate":[{"q":"There are ___ (very few / very little) parks in my neighbourhood.","a":["very few"]},{"q":"This phone isn't ___ (fast / enough).","a":["fast enough"]},{"q":"We've got ___ (enough / chairs / not) for everyone.","a":["not enough chairs"]},{"q":"There's ___ hope that they will finish the bridge on time. (almost none)","o":["little","a little","few"],"a":0},{"q":"I've got ___ ideas for the project. Can I share them?","o":["a few","few","a little"],"a":0},{"q":"Some people spend ___ time online.","o":["too much","too many","enough of"],"a":0},{"q":"There are ___ of charging points, so you'll find one easily.","a":["plenty","lots"]},{"r":"The flat isn't big enough for five people."}],"advanced":[{"q":"Correct the mistake: 'There are too much buildings and not enough trees.'","a":["There are too many buildings and not enough trees.","There are too many buildings and not enough trees"]},{"q":"Correct the mistake: 'We don't have money enough.'","a":["We don't have enough money.","We don't have enough money"]},{"q":"Which sentence is negative in meaning?","o":["I have a few friends here.","I have few friends here.","I have plenty of friends here."],"a":1},{"q":"Rewrite with 'too': 'The tower isn't safe enough.' → The tower is ___ .","a":["too dangerous","too unsafe"]},{"q":"Rewrite with 'enough': 'The bike is too slow to win the race.' → The bike isn't ___ to win the race.","a":["fast enough","quick enough"]},{"q":"Choose: 'Hardly anyone came. There were ___ people at the event.'","o":["few","a few","plenty of"],"a":0},{"q":"Complete: 'There's ___ concrete in modern cities and ___ green space.' (more than we want / less than we need)","a":["too much / not enough"],"h":"Write both separated by /"},{"r":"There are plenty of affordable flats in the new district."}]}}],"files":{"list":"downloads/unit7/vocabulary-list.pdf","vocab":{"basic":"downloads/unit7/vocabulary-basic.pdf","intermediate":"downloads/unit7/vocabulary-intermediate.pdf","advanced":"downloads/unit7/vocabulary-advanced.pdf"},"grammar":{"passive":{"basic":"downloads/unit7/grammar-passive-basic.pdf","intermediate":"downloads/unit7/grammar-passive-intermediate.pdf","advanced":"downloads/unit7/grammar-passive-advanced.pdf"},"quantifiers":{"basic":"downloads/unit7/grammar-quantifiers-basic.pdf","intermediate":"downloads/unit7/grammar-quantifiers-intermediate.pdf","advanced":"downloads/unit7/grammar-quantifiers-advanced.pdf"}}}},{"id":8,"title":"Game on","topic":"Video games, stories and the ideas behind them","color":"#4b4bff","vocab":[{"name":"Gaming","words":[["addictive","adj","so enjoyable that it's difficult to stop","adictivo/a","This puzzle game is really *addictive*."],["challenge","noun","something difficult that tests your ability","reto, desafío","The last level is a real *challenge*."],["competitor","noun","a person who takes part in a competition","competidor/a","There were 200 *competitors* in the tournament."],["crash","verb","to stop working suddenly (computer or game)","colgarse, bloquearse","The game *crashed* just before I saved it!"],["development","noun","the process of creating something new","desarrollo","The game was in *development* for five years."],["educational","adj","that helps you learn","educativo/a","Some *educational* games teach maths."],["entertaining","adj","fun and enjoyable","entretenido/a","The story mode is very *entertaining*."],["escape","noun / verb","a way to forget about real life for a while","evasión / escapar","For me, gaming is an *escape* from stress."],["expand someone's mind","phrase","to help someone think in new ways","abrir la mente","Strategy games can *expand your mind*."],["gaming","noun","the activity of playing video games","los videojuegos (actividad)","*Gaming* is a huge industry."],["hand-eye coordination","noun","the ability to use your eyes and hands together","coordinación ojo-mano","Action games improve *hand-eye coordination*."],["influence","noun / verb","the power to change how people think or act","influencia / influir","Do games have a bad *influence* on young people?"],["plot","noun","the story of a book, film or game","trama, argumento","The *plot* has a surprising ending."],["social part","noun","the part of an activity where you interact with others","parte social","The *social part* of online games is important to me."],["take risks","phrase","to do something that could be dangerous or fail","arriesgarse","In this game you have to *take risks* to win."]]},{"name":"Abstract nouns","words":[["beauty","noun","the quality of being beautiful","belleza","The *beauty* of the game's world is amazing."],["growth","noun","the process of becoming bigger or better","crecimiento","The character's *growth* is the heart of the story."],["happiness","noun","the feeling of being happy","felicidad","Winning brought him great *happiness*."],["identity","noun","who or what a person is","identidad","The hero discovers his true *identity*."],["joy","noun","a feeling of great happiness","alegría","She jumped with *joy* when she finished the level."],["justice","noun","fair treatment for everyone","justicia","The main character fights for *justice*."],["loss","noun","the fact of losing someone or something","pérdida","The game deals with the *loss* of a family member."],["mystery","noun","something strange that people can't explain","misterio","Who stole the crown? It's a *mystery*."],["reality","noun","what is real, not imaginary","realidad","Virtual *reality* games feel very real."],["strength","noun","the quality of being strong","fuerza","You need *strength* to carry the sword."],["truth","noun","the real facts about something","verdad","In the end, she tells him the *truth*."],["victory","noun","success in a game, competition or war","victoria","The team celebrated their *victory*."]]},{"name":"Extra: Idiomatic phrases","extra":true,"words":[["a piece of cake","idiom","very easy","pan comido","The first level was *a piece of cake*."],["haven't got a clue","idiom","don't know anything about it","no tener ni idea","I *haven't got a clue* how to beat this boss."],["in a nutshell","idiom","in a few words","en pocas palabras","*In a nutshell*, it's the best game of the year."],["lose track (of time)","idiom","to not notice how much time has passed","perder la noción (del tiempo)","I always *lose track* of time when I play."],["out of nowhere","idiom","suddenly and unexpectedly","de la nada","A dragon appeared *out of nowhere*."],["over the moon","idiom","extremely happy","encantado/a, en una nube","I was *over the moon* when I won."],["to be a pain","idiom","to be annoying","ser un rollo, ser un pesado","This level is *a pain*!"]]}],"grammar":[{"id":"determiners","title":"Determiners","short":"all, both, each, every, either, neither, none, no, whole","slides":[{"k":"title","h":"Determiners","sub":"Game on: every player, both teams, neither option","hook":"Do all your friends play video games? Are both of your parents competitive?"},{"k":"table","h":"Talking about two things","cols":["Determiner","Meaning","Example"],"rows":[["both (of)","the two together (+ plural verb)","Both games are entertaining. / Both of them are entertaining."],["either (of)","one or the other","You can choose either character."],["neither (of)","not one and not the other","Neither competitor won. / Neither of us won."]]},{"k":"table","h":"Talking about three or more","cols":["Determiner","Meaning","Example"],"rows":[["all (of)","the whole group (+ plural)","All the competitors start with three lives."],["every","all, seen as a group (+ singular)","Every level is a new challenge."],["each","every one, seen separately (+ singular)","Each player has a different identity."],["no / none of","not any","There are no saves left. / None of my friends find it addictive."]]},{"k":"text","h":"whole and all","p":["'the whole' + singular countable noun = all of something.","'all' + plural or uncountable nouns."],"ex":["I played **the whole** game in one weekend – I lost track of time!","I've played **all** the games in the series.","We spent **all day** gaming. = **the whole day**"]},{"k":"text","h":"of + pronouns","p":["Before pronouns (us, you, them) we must use 'of'.","Before 'the', 'my', 'these', 'of' is usual (but optional with all / both)."],"ex":["**Both of us** were over the moon after our victory.","**Neither of them** knew the truth about the plot.","**Each of the** levels is harder than the last."]},{"k":"context","h":"Grammar in context","kind":"Game review","title":"Shadow Quest: 9/10","text":["**Every** level is a challenge, and **each** character has a special strength. You can play with **either** the knight or the thief – **both** are fun!","**All** my friends love the plot, which is full of mystery. **None of** us expected the ending!","The only problem? The game crashed twice, and **neither** time could I save. In a nutshell: it's addictive, entertaining and great for hand-eye coordination."]},{"k":"mistakes","h":"Watch out!","items":[["Every players have a mission.","Every player has a mission.","every + singular noun + singular verb."],["Both of they are good competitors.","Both of them are good competitors.","Use object pronouns after 'of'."],["I didn't like neither game.","I liked neither game. / I didn't like either game.","Don't use two negatives."]]},{"k":"check","q":"___ of my two brothers play online. They prefer football.","o":["Neither","Both","Either"],"a":0,"e":"Not one and not the other → neither."},{"k":"check","q":"___ competitor in the tournament gets a medal.","o":["All","Every","Both"],"a":1,"e":"every + singular noun."},{"k":"sum","h":"Remember","p":["Two things: both, either, neither.","Three or more: all, every, each, none.","every / each + singular noun.","of + pronoun: both of us, none of them."]}],"ex":{"basic":[{"q":"___ my parents like playing chess. (the two)","o":["Both","Every","Each"],"a":0},{"q":"___ level has a boss at the end.","o":["Every","All","Both"],"a":0},{"q":"There are ___ lives left. Game over!","o":["no","none","neither"],"a":0},{"q":"You can play with ___ hand – left or right.","o":["either","both","all"],"a":0},{"q":"___ the players are ready.","o":["All","Every","Each"],"a":0},{"q":"___ of my friends has got this game. Nobody has it.","a":["None"]},{"r":"Each player has three lives."},{"q":"I played the ___ game in one day.","o":["whole","all","every"],"a":0}],"intermediate":[{"q":"___ of the two games are expensive. (both are)","a":["Both"]},{"q":"I tried two controllers, but ___ of them worked.","o":["neither","either","both"],"a":0},{"q":"Do you want pizza or pasta? – I don't mind. ___ is fine.","o":["Either","Neither","Both"],"a":0},{"q":"___ of us knew the answer, so we lost the quiz.","o":["None","No","All"],"a":0},{"q":"We spent the ___ weekend at the gaming festival.","a":["whole"]},{"q":"___ competitor receives a medal, even the last one.","o":["Each","All","Both"],"a":0},{"q":"Correct: 'Every games have a plot.' → Every game ___ a plot.","a":["has"]},{"r":"Both of them were over the moon after their victory."}],"advanced":[{"q":"Correct the mistake: 'Both of we play online.'","a":["Both of us play online.","Both of us play online"]},{"q":"Correct the mistake: 'I don't like neither of these games.'","a":["I don't like either of these games.","I like neither of these games.","I don't like either of these games"]},{"q":"Rewrite: 'Sam didn't win and Ana didn't win.' → ___ Sam nor Ana won.","a":["Neither"]},{"q":"Rewrite: 'You can choose the red team or the blue team.' → You can choose ___ the red team or the blue team.","a":["either"]},{"q":"Choose: '___ the people in my class has a different favourite game.'","o":["Each of","All of","Every of"],"a":0},{"q":"Rewrite: 'Not one of the levels is easy.' → ___ of the levels is easy.","a":["None"]},{"q":"Choose: 'The ___ class went to the gaming museum.'","o":["whole","all","every"],"a":0},{"r":"Neither of the games crashed during the tournament."}]}},{"id":"relative","title":"Relative clauses","short":"Defining and non-defining: who, which, that, where, whose, when","slides":[{"k":"title","h":"Relative clauses","sub":"Game on: the hero who saved the kingdom","hook":"Describe your favourite game character without saying their name. Can your partner guess who it is?"},{"k":"table","h":"Relative pronouns","cols":["Pronoun","For","Example"],"rows":[["who","people","The competitor who takes the most risks usually wins."],["which","things, animals","The game which I bought is really addictive."],["that","people or things (defining only)","It's the level that always crashes."],["where","places","This is the castle where the mystery begins."],["whose","possession","She's the hero whose identity is a secret."],["when","times","I remember the day when I won my first victory."]]},{"k":"text","h":"Defining relative clauses","p":["They give essential information: which person or thing we mean. No commas.","We can omit who / which / that when it is the object of the clause."],"ex":["The game **that** I played yesterday was really educational.","The game **(that)** I played yesterday was really educational.","The person **who** developed Minecraft is Swedish."]},{"k":"text","h":"Non-defining relative clauses","p":["They give extra information. We put them between commas. We can't use 'that' and we can't omit the pronoun."],"ex":["Tetris, **which** was created in 1984, is still entertaining.","My cousin Lucía, **who** is a pro gamer, has amazing hand-eye coordination.","Japan, **where** many famous games were developed, is my dream trip."]},{"k":"table","h":"Compare","cols":["Defining","Non-defining"],"rows":[["My brother who lives in Paris plays chess. (I have more than one brother)","My brother, who lives in Paris, plays chess. (I have only one brother)"],["No commas","Commas"],["that is OK","No that"]]},{"k":"context","h":"Grammar in context","kind":"Storyboard · New game","title":"The Lost Kingdom","text":["Mira is a girl **who** lives in a world **where** the sun never rises. Her father, **whose** sword is magic, disappeared on the night **when** the darkness began.","Mira finds a map **which** shows the way to the Tower of Truth. The journey, **which** is full of danger, will test her strength.","The player **who** helps Mira must make choices **that** change the plot. Will she find justice – or loss?"]},{"k":"mistakes","h":"Watch out!","items":[["Zelda, that is my favourite game, is quite old.","Zelda, which is my favourite game, is quite old.","No 'that' in non-defining clauses."],["The man which designed the plot is famous.","The man who designed the plot is famous.","Use who for people."],["This is the level where I always lose there.","This is the level where I always lose.","Don't repeat the place."]]},{"k":"check","q":"That's the gamer ___ videos have 10 million views.","o":["who","whose","which"],"a":1,"e":"Possession → whose."},{"k":"check","q":"Fortnite, ___ came out in 2017, is free to play.","o":["that","which","who"],"a":1,"e":"Non-defining clause with commas → which (not that)."},{"k":"sum","h":"Remember","p":["who = people, which = things, where = places, whose = possession, when = time.","Defining: essential info, no commas, 'that' is OK.","Non-defining: extra info, commas, no 'that'."]}],"ex":{"basic":[{"q":"A gamer is a person ___ plays video games.","o":["who","which","where"],"a":0},{"q":"This is the console ___ I got for my birthday.","o":["which","who","where"],"a":0},{"q":"That's the shop ___ I bought my game.","o":["where","which","who"],"a":0},{"q":"He's the boy ___ sister won the tournament.","o":["whose","who","which"],"a":0},{"q":"I remember the day ___ I got my first phone.","o":["when","where","who"],"a":0},{"q":"A controller is a thing ___ you use to play.","a":["that","which"]},{"r":"This is the game that I told you about."},{"q":"The girl ___ designed this level is only fifteen.","a":["who","that"]}],"intermediate":[{"q":"Mario, ___ first appeared in 1981, is a plumber.","o":["who","that","whose"],"a":0},{"q":"My laptop, ___ is very old, crashed again.","o":["which","that","who"],"a":0},{"q":"Join: 'This is my friend. Her dad works at Nintendo.' → This is my friend ___ dad works at Nintendo.","a":["whose"]},{"q":"Join: 'That's the arcade. We met there.' → That's the arcade ___ we met.","a":["where"]},{"q":"In which sentence can you omit the pronoun?","o":["The game that I bought is great.","The man who lives here is a coder.","Madrid, which is big, has many arcades."],"a":0},{"q":"The game ___ won the award was made by a small team.","o":["that","who","where"],"a":0},{"q":"Minecraft, ___ was created in Sweden, is the best-selling game ever.","a":["which"]},{"r":"The competitor who took the most risks won the victory."}],"advanced":[{"q":"Join with a non-defining clause: 'Tokyo has amazing game shops. I visited it last year.' → Tokyo, ___ , has amazing game shops.","a":["which I visited last year"]},{"q":"Join: 'The developer is famous. Her game sold 5 million copies.' → The developer ___ is famous.","a":["whose game sold 5 million copies"]},{"q":"Correct the mistake: 'My best friend, that loves RPGs, is coming over.'","a":["My best friend, who loves RPGs, is coming over.","My best friend, who loves RPGs, is coming over"]},{"q":"Which sentence means the speaker has only one sister?","o":["My sister who plays chess is twelve.","My sister, who plays chess, is twelve.","My sister that plays chess is twelve."],"a":1},{"q":"Correct the mistake: 'This is the level where I always lose there.'","a":["This is the level where I always lose.","This is the level where I always lose"]},{"q":"Add commas if needed: 'The game which I'm playing now is really entertaining.'","o":["No commas – it's defining.","The game, which I'm playing now, is really entertaining.","Commas after 'game' only."],"a":0},{"q":"Join: '2020 was a strange year. Many people started gaming then.' → 2020, ___ , was a strange year.","a":["when many people started gaming"]},{"r":"The plot which is full of mystery keeps you playing for hours."}]}}],"files":{"list":"downloads/unit8/vocabulary-list.pdf","vocab":{"basic":"downloads/unit8/vocabulary-basic.pdf","intermediate":"downloads/unit8/vocabulary-intermediate.pdf","advanced":"downloads/unit8/vocabulary-advanced.pdf"},"grammar":{"determiners":{"basic":"downloads/unit8/grammar-determiners-basic.pdf","intermediate":"downloads/unit8/grammar-determiners-intermediate.pdf","advanced":"downloads/unit8/grammar-determiners-advanced.pdf"},"relative":{"basic":"downloads/unit8/grammar-relative-basic.pdf","intermediate":"downloads/unit8/grammar-relative-intermediate.pdf","advanced":"downloads/unit8/grammar-relative-advanced.pdf"}}}}];
